/* 10వ తరగతి – hin పూర్తి పాఠాలు (tools/split/split_class10.py) */
((window.RAAY_TBF=window.RAAY_TBF||{})[10]=window.RAAY_TBF[10]||{})["hin"]=[{"id":"hi1","no":1,"t":"बरसते बादल","m":[6],"ty":"कविता (కవిత)","th":"प्रकृति – వర్షాకాల సౌందర్యం","by":"सुमित्रानंदन पंत","sum":"వర్షాకాలం (సావన్) లో ప్రకృతి సౌందర్యాన్ని కవి ధ్వని పదాలతో వర్ణించాడు. \"झम-झम\" మేఘాలు కురుస్తున్నాయి, చెట్ల నుండి \"छम-छम\" చినుకులు జారుతున్నాయి, దట్టమైన మేఘాల మధ్య మెరుపు \"चम-चम\" మెరుస్తోంది; పగటి చీకటిలో మనసులో కలలు మేల్కొంటున్నాయి. కప్పలు \"टर-टर\", కీచురాళ్ళు \"झन-झन\", నెమళ్ళు \"म्यवँ\", చాతక పక్షులు \"पीउ-पीउ\" అంటున్నాయి; సోన్‌బలాక్ (కొంగలు) ఎగురుతున్నాయి; మేఘాలు గర్జిస్తున్నాయి. \"रिमझिम\" చినుకుల స్వరాలు ఏదో చెబుతున్నట్లున్నాయి, ఒళ్ళు పులకిస్తోంది; ధారల మీద ధారలు భూమిపై పడి మట్టి కణకణంలో, గడ్డి పరకల్లో పులకింత కలుగుతోంది. కవి మనసు వాన ధారల ఊయలలో ఊగుతోంది – అందరూ కలిసి సావన్ పాట పాడాలని, ఇంద్రధనుస్సు ఊయలలో ఊగాలని, జీవితంలో మళ్ళీ మళ్ళీ మనోహరమైన సావన్ రావాలని కోరుకుంటాడు.","pts":["कवि: सुमित्रानंदन पंत (1900–1977) – అల్మోడా జిల్లా కౌసానీ గ్రామం; \"ప్రకృతి సుకుమార కవి\".","పురస్కారాలు: साहित्य अकादमी, \"चिदंबरा\" కు ज्ञानपीठ पुरस्कार.","రచనలు: वीणा, ग्रंथि, पल्लव, गुंजन, युगांत, स्वर्णकिरण, कला और बूढ़ा चाँद, चिदंबरा.","విధ: कविता – నాద (ధ్వని) తో పాడదగినది; अनुप्रास अलंकार అందమైన ప్రయోగం.","ధ్వని పదాలు: झम-झम (మేఘాలు), छम-छम (చినుకులు), चम-चम (మెరుపు), टर-टर (కప్పలు), झन-झन (కీచురాళ్ళు), पीउ-पीउ (చాతకం).","तत्सम – तद्भव: श्रावण–सावन, मयूर–मोर, सूर्य–सूरज, स्वप्न–सपना, कृपा–किरपा."],"w":[["मेघ","బాదల్ – మేఘం"],["सावन","శ్రావణ మాసం"],["तरु","చెట్టు (पेड़)"],["घन","దట్టమైన మేఘం"],["उर","హృదయం, లోపలి భాగం"],["तम","చీకటి"],["दादुर","కప్ప (मेंढक)"],["झिल्ली","కీచురాయి (झींगुर)"],["चातक","చాతక పక్షి"],["सोनबलाक","బంగారు రంగు కొంగ"],["क्रंदन","అరుపు, రోదన"],["गगन","ఆకాశం"],["रज","మట్టి, ధూళి"],["तृण","గడ్డి పరక"],["पुलकावलि","పులకింత"],["मनभावन","మనసుకు నచ్చే"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["अनुप्रास अलंकार: ఒకే అక్షరం/పదం మళ్ళీ మళ్ళీ వచ్చి ధ్వని సౌందర్యం పెరగడం – \"झम-झम-झम-झम मेघ बरसते हैं सावन के\".","तत्सम शब्द: సంస్కృతం నుండి మార్పు లేకుండా వచ్చినవి (श्रावण, मयूर, सूर्य). तद्भव शब्द: మార్పు చెందినవి (सावन, मोर, सूरज).","पुनरुक्ति शब्द: चम-चम, तृण-तृण, फिर-फिर.","द्वंद्व समास: पेड़-पौधे (पेड़ और पौधे), पशु-पक्षी (पशु और पक्षी).","वर्तमानकालिक कृदंत विशेषण: बरसते बादल, झरती धाराएँ, गिरती बूँदें, बहता पानी."]},"qa":[["कवि का नाम क्या है?","सुमित्रानंदन पंत।"],["मेघ कैसे बरसते हैं?","झम-झम-झम-झम सावन के मेघ बरसते हैं।"],["बिजली कहाँ चमक रही है?","घने बादलों (घन) के उर में चम-चम चमक रही है।"],["दादुर और झिल्ली क्या करते हैं?","दादुर टर-टर करते हैं, झिल्ली झन-झन बजती है।"],["कवि क्या चाहता है?","जीवन में मनभावन सावन फिर-फिर आए, सब मिलकर इंद्रधनुष के झूले में झूलें।"],["कविता में कौन-सा अलंकार है?","अनुप्रास अलंकार।"]],"act":"वर्षा, बादल, नदी, सागर, सूरज, चाँद, झरने में से किसी एक विषय पर प्रकृति वर्णन से जुड़ी कविताओं का संग्रह करके कक्षा में प्रदर्शन कीजिए।","kn":"\"प्रकृति के क्षेत्र में जो साधना करते हैं, उन्हें सहज ही शक्ति प्राप्त हो जाती है।\" – रवींद्रनाथ ठाकुर. \"सौंदर्य का आदर्श सादगी और शांति है।\" – गेटे.","qz":[["\"बरसते बादल\" के कवि कौन हैं?","सुमित्रानंदन पंत","प्रेमचंद","रामधारी सिंह दिनकर","सूर्यकांत त्रिपाठी निराला"],["सुमित्रानंदन पंत का जन्म कहाँ हुआ?","कौसानी (अल्मोड़ा)","इलाहाबाद","लमही","बनारस"],["पंत को ज्ञानपीठ पुरस्कार किस रचना के लिए मिला?","चिदंबरा","पल्लव","गुंजन","वीणा"],["\"झम-झम\" कौन बरसते हैं?","मेघ","बूँदें","बिजली","मोर"],["\"छम-छम\" क्या गिरती हैं?","बूँदें (तरुओं से छनकर)","बिजली","पत्ते","फूल"],["\"दादुर\" का अर्थ क्या है?","मेंढक","मोर","कोयल","झींगुर"],["\"टर-टर\" कौन करते हैं?","दादुर","झिल्ली","चातक","मोर"],["\"पीउ-पीउ\" कौन बोलता है?","चातक","मोर","कोयल","दादुर"],["कवि का मन किसमें झूलता है?","पंकिल वारि की धार में","पेड़ की डाल में","नदी में","बादल में"],["सब जन किसके झूले में झूलें?","इंद्रधनुष के","पेड़ के","बादल के","चाँद के"],["\"तरु\" का पर्याय शब्द?","पेड़","बादल","आकाश","पानी"],["\"सावन\" का तत्सम रूप?","श्रावण","सावण","स्रावन","शावन"],["\"झम-झम-झम-झम मेघ बरसते हैं\" – अलंकार?","अनुप्रास","उपमा","रूपक","उत्प्रेक्षा"],["\"पेड़-पौधे\" में समास?","द्वंद्व समास","तत्पुरुष","द्विगु","बहुव्रीहि"]],"wb":{"mis":"तत्सम = సంస్కృతం నుండి మార్పు లేకుండా (सूर्य, स्वप्न, चंद्र); तद्भव = మార్పు చెందినది (सूरज, सपना, चाँद) – తిరగేసి రాయకండి.","qz":[["\"सपना\" का तत्सम रूप?","स्वप्न","सपन","सोपना","स्पना"],["\"सूरज\" का तत्सम रूप?","सूर्य","सूरय","सूर","सुरज"],["\"चंद्र\" का तद्भव रूप?","चाँद","चंदा","चंदर","चंद्रमा"],["\"मन को भाने वाला\" – एक शब्द?","मनभावन","मनमोहन","मनपसंद","मनोरथ"],["\"पशु-पक्षी\" में समास?","द्वंद्व","द्विगु","कर्मधारय","अव्ययीभाव"],["\"गगन\" का पर्याय?","आकाश","धरती","सागर","पर्वत"]],"pg":"8–12","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":10,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन – कोयल (प्रश्न) (పుట 8)","कविता के पास के प्रश्न (పుట 9)","अर्थग्राह्यता-प्रतिक्रिया (పుట 10)","अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 11)","अलंकार; परियोजना कार्य (పుట 12)"]},"tg":[["पूर्व पठन – कोयल (प्रश्न) (పుట 8)",["1. कोयल मीठे गीत गाती है। 2. प्यासी धरती मेघों (बादलों) से पानी माँगती है। 3. बादल बरसकर धरती को हरा-भरा बनाते हैं, नदियाँ-तालाब भरते हैं, पेड़-पौधे, फूल खिलते हैं, मोर नाचते हैं – इस तरह प्रकृति की शोभा बढ़ाते हैं।"]],["कविता के पास के प्रश्न (పుట 9)",["1. मेघ झम-झम बरसते हैं, बिजली घने बादलों में चम-चम चमकती है, बूँदें तरुओं से छन-छनकर छम-छम गिरती हैं, मेघ घुमड़-घुमड़ कर गर्जन करते हैं। 2. बूँदों का रिमझिम स्वर, मोर का नाच, चातक की पीउ-पीउ, उड़ते सोनबलाक, इंद्रधनुष, हरे तृण – मन को छू लेते हैं। 3. वर्षा से मिट्टी के कण-कण में और घास के तिनके-तिनके में नया जीवन आ गया है, सब पुलकित (रोमांचित) होकर खुशी से झूम उठे हैं।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 10)",["अ) 1. वर्षा से धरती हरी-भरी होती है, पेड़-पौधे, फसलें उगती हैं, नदियाँ-तालाब भरते हैं, पशु-पक्षी प्रसन्न होते हैं – इसलिए धरती की शोभा का प्रमुख कारण वर्षा है। 2. घने बादल काले-काले होकर आकाश में घुमड़ते हैं, गर्जन करते हैं, उनमें बिजली चमकती है, दिन में भी अँधेरा छा जाता है।","आ) 1. झम-झम-झम-झम मेघ बरसते हैं सावन के। 2. घुमड़-घुमड़ गिर मेघ गगन में भरते गर्जन। 3. धाराओं पर धाराएँ झरती धरती पर।","इ) 1. \"चम-चम बिजली चमक रही रे उर में घन के, थम-थम दिन के तम में सपने जगते मन के।\" 2. \"रज के कण-कण में तृण-तृण की पुलकावलि भर।\" 3. \"इंद्रधनुष के झूले में झूलें मिल सब जन, फिर-फिर आये जीवन में सावन मनभावन।\"","ई) 1. (ई) बादल 2. (अ) चिड़िया 3. (इ) चाँद-सितारे 4. (आ) नभ 5. (अ) प्रकृति"]],["अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 11)",["अ) 1. वर्षा से पीने का पानी, खेती के लिए जल मिलता है; फसलें, पेड़-पौधे उगते हैं; पशु-पक्षियों को भोजन-पानी मिलता है; नदियाँ, तालाब, कुएँ भरते हैं – इसलिए वर्षा सभी प्राणियों के जीवन का आधार है। 2. वर्षा ऋतु में आकाश में काले बादल छा जाते हैं, बिजली चमकती है, ठंडी हवा चलती है, चारों ओर हरियाली छा जाती है, मोर नाचते हैं, मेंढक टर्राते हैं, इंद्रधनुष निकलता है – यह दृश्य बहुत मनमोहक होता है।","आ) कवि ने सावन की वर्षा का ध्वनिपूर्ण चित्रण किया है – मेघ झम-झम बरसते हैं, बूँदें छम-छम गिरती हैं, बिजली चम-चम चमकती है; मेंढक टर-टर, झींगुर झन-झन, मोर और चातक बोलते हैं; सोनबलाक उड़ते हैं; धरती पर धाराएँ गिरती हैं, कण-कण और तृण-तृण पुलकित हो जाते हैं; कवि का मन झूला झूलता है और वह चाहता है कि सावन बार-बार आए।","इ) कविता (उदा.): \"काले-काले बादल आए, / ठंडी-ठंडी हवा लाए। / रिमझिम-रिमझिम बरसा पानी, / हरी हो गई धरती रानी। / मोर नाचे, कोयल गाए, / सबके मन को खूब भाए।\"","ई) सावन में प्रकृति हरी-भरी और सुंदर हो जाती है, सब ओर खुशी छा जाती है, लोग झूले झूलते हैं, त्योहार मनाते हैं – यह आनंद जीवन में बार-बार मिले, इसलिए कवि ने ऐसा कहा।","भाषा की बात (अ) 1. तरु = पेड़, वृक्ष – पेड़ हमें छाया देते हैं; गगन = आकाश, नभ – आकाश में तारे चमकते हैं; घन = बादल, मेघ – बादल गरजते हैं। 2. सावन – श्रावण; सपना – स्वप्न; सूरज – सूर्य। 3. गण – गन; मयूर – मोर; चंद्र – चाँद। 4. बिजली चम-चम चमकती है; खेत में तृण-तृण हरा है; मैं यह कविता फिर-फिर पढ़ता हूँ।","(आ) 1. \"धाराओं\" – बहुवचन, विकारी रूप (पर परसर्ग के कारण); \"धाराएँ\" – बहुवचन, मूल रूप; \"धरती\" – एकवचन। 2. \"झूले\" – पुल्लिंग संज्ञा (झूला का विकारी रूप); \"झूलें\" – क्रिया (झूलना)। 3. बादल – जातिवाचक संज्ञा, पुल्लिंग, बहुवचन, कर्ता कारक, \"बरसते हैं\" क्रिया का कर्ता। 4. मनभावन। 5. पेड़-पौधे, पशु-पक्षी – द्वंद्व समास।","(इ) उड़ती चिड़िया सुंदर लगती है; दौड़ता घोड़ा तेज़ होता है; खिलते फूल मन मोहते हैं; चमकते तारे अच्छे लगते हैं; गाती कोयल मीठी लगती है।"]],["अलंकार; परियोजना कार्य (పుట 12)",["अनुप्रास अलंकार: \"झम-झम-झम-झम\", \"छम-छम-छम\" – एक ही वर्ण/शब्द बार-बार आने से ध्वनि-सौंदर्य बढ़ा है।","परियोजना: वर्षा/बादल/नदी आदि पर कविताएँ (उदा. \"बादल राग\" – निराला, \"मेघ आए\" – सर्वेश्वर दयाल सक्सेना) संग्रह करके कक्षा में प्रदर्शन।"]]]},{"id":"hi2","no":2,"t":"ईदगाह","m":[6],"ty":"कहानी (కథ)","th":"त्याग, दादी–पोते का प्रेम","by":"प्रेमचंद","sum":"రమజాన్ 30 రోజాల తర్వాత ఈద్ వచ్చింది. తల్లిదండ్రులు లేని నాలుగైదేళ్ళ హామిద్ తన పేద నాయనమ్మ (దాదీ) అమీనా దగ్గర ఉంటాడు. ఈద్గాహ్‌కు మిత్రులతో వెళ్ళేటప్పుడు అతని దగ్గర కేవలం మూడు పైసలే ఉన్నాయి; మహమూద్ దగ్గర 12, మోహసిన్ దగ్గర 15 పైసలు. మేళాలో మిత్రులు రంగులరాట్నం ఎక్కారు, బొమ్మలు (భిశ్తీ, సిపాయి, వకీలు), మిఠాయిలు కొన్నారు; హామిద్ దూరంగా నిలబడి మనసు చంపుకున్నాడు. రొట్టెలు కాల్చేటప్పుడు దాదీ చేతులు కాలుతాయని గుర్తొచ్చి, ఇనుప దుకాణంలో ఆరు పైసల పటకారు (चिमटा) ను బేరమాడి మూడు పైసలకు కొన్నాడు. మిత్రులు ఎగతాళి చేసినా, తన పటకారు గొప్పతనాన్ని వాదించి గెలిచాడు – మిత్రుల మట్టి బొమ్మలు విరిగిపోయాయి. ఇంటికి వచ్చాక \"ఏమీ తినకుండా, తాగకుండా ఈ పటకారు ఎందుకు తెచ్చావు?\" అని అమీనా మొదట కోపగించింది; \"నీ చేతులు పెనం మీద కాలుతాయి కదా\" అనగానే ఆమె కోపం మూగ ప్రేమగా మారి, ఏడుస్తూ హామిద్‌ను దీవించింది. పిల్లవాడి త్యాగం, వివేకం, పెద్దలపై ప్రేమ ఈ కథ సారం.","pts":["రచయిత: प्रेमचंद (1880–1936) – కాశీ దగ్గర లమహీ, పేద కుటుంబం; అసలు పేరు धनपत राय श्रीवास्तव; \"उपन्यास सम्राट\".","సుమారు డజను నవలలు, 300 కి పైగా కథలు; కథలు \"मानसरोवर\" పేరుతో 8 భాగాలు.","నవలలు: गोदान, गबन, सेवासदन, निर्मला, कर्मभूमि, रंगभूमि, कायाकल्प, प्रतिज्ञा, मंगलसूत्र. కథలు: पंचपरमेश्वर, बड़े घर की बेटी, कफ़न, ईदगाह.","విధ: कहानी – \"कह\" ధాతువు + \"आनी\" ప్రత్యయం; సంఘటనను అందంగా చెప్పడం.","పాత్రలు: हामिद, अमीना (దాదీ), महमूद (12 పైసలు), मोहसिन (15 పైసలు, భిశ్తీ కొన్నాడు), नूरे, सम्मी.","హామిద్ కొన్నది: चिमटा (ఆరు పైసలది – మూడు పైసలకు)."],"w":[["ईद","ముస్లింల పండుగ"],["रोज़ा","ఉపవాసం"],["ईदगाह","ఈద్ నమాజ్ చేసే స్థలం"],["मेला","జాతర"],["चिमटा","పటకారు"],["भिश्ती","నీళ్ళు మోసేవాడు (బొమ్మ)"],["कचोटना","బాధించు"],["सेवइयाँ","సేమియా"],["तवा","పెనం"],["कलेजा मज़बूत करना","ధైర్యం తెచ్చుకోవడం"],["दिल बैठ जाना","నిరాశ చెందడం"],["मूक स्नेह","మాటలు లేని ప్రేమ"],["अपराधी","దోషి"],["प्रसन्न","సంతోషం"],["बुज़ुर्ग","పెద్దవారు"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["उपसर्ग: पद के आगे जुड़ने वाला अंश – बे+समझ, सद्+भाव, नि+डर.","प्रत्यय: पद के पीछे जुड़ने वाला अंश – दुकान+दार, भड़क+ईला, गरीब+ई.","भाववाचक संज्ञा: मीठा → मिठास, प्रसन्न → प्रसन्नता, बूढ़ा → बुढ़ापा.","काल परिवर्तन: आयी (सामान्य भूत), आयी है (आसन्न भूत), आयी थी (पूर्ण भूत), आयी होगी (संदिग्ध भूत), आ रही थी (अपूर्ण भूत).","मुहावरे: दिल बैठ जाना, कलेजा मज़बूत करना, छाती से लगाना, दिल कचोटना."]},"qa":[["हामिद के पास कितने पैसे थे?","केवल तीन पैसे।"],["अमीना कौन थी?","हामिद की दादी।"],["महमूद और मोहसिन के पास कितने पैसे थे?","महमूद के पास बारह, मोहसिन के पास पंद्रह पैसे।"],["हामिद ने चिमटा क्यों खरीदा?","रोटियाँ सेंकते समय तवे से दादी की उँगलियाँ जल जाती थीं।"],["चिमटे की कीमत क्या थी?","छह पैसे; हामिद ने तीन पैसे में खरीदा।"],["अमीना का क्रोध किसमें बदल गया?","स्नेह (मूक स्नेह) में।"]],"act":"वरिष्ठ नागरिकों (वयोवृद्धों) के प्रति आदर-सम्मान की भावना से जुड़ी कोई कहानी ढूँढ़कर लाइए और कक्षा में प्रस्तुत कीजिए।","kn":"\"लगन को काँटों की परवाह नहीं होती।\" – प्रेमचंद. पठन हेतु: \"यह रास्ता कहाँ जाता है\".","qz":[["\"ईदगाह\" कहानी के लेखक?","प्रेमचंद","सुमित्रानंदन पंत","विष्णु प्रभाकर","मन्नू भंडारी"],["प्रेमचंद का असली नाम?","धनपत राय श्रीवास्तव","नवाब राय","हरिवंश राय","रामधारी सिंह"],["प्रेमचंद को क्या कहा जाता है?","उपन्यास सम्राट","राष्ट्रकवि","प्रकृति कवि","कहानी के जनक"],["प्रेमचंद की कहानियों का संकलन?","मानसरोवर","चिदंबरा","गोदान","सेवासदन"],["हामिद के पास कितने पैसे थे?","तीन","बारह","पंद्रह","छह"],["हामिद की दादी का नाम?","अमीना","सम्मी","नूरी","फ़ातिमा"],["मोहसिन ने कौन-सा खिलौना खरीदा?","भिश्ती","सिपाही","वकील","चिमटा"],["हामिद ने क्या खरीदा?","चिमटा","खिलौना","मिठाई","गेंद"],["चिमटे की असली कीमत?","छह पैसे","तीन पैसे","बारह पैसे","पंद्रह पैसे"],["हामिद ने चिमटा क्यों खरीदा?","दादी की उँगलियाँ तवे से न जलें","खेलने के लिए","बेचने के लिए","दोस्तों को दिखाने के लिए"],["कीमत सुनकर हामिद का दिल…","बैठ गया","खुश हुआ","टूट गया","भर आया"],["अमीना का क्रोध किसमें बदल गया?","स्नेह में","दुख में","डर में","हँसी में"],["\"निडर\" में उपसर्ग?","नि","डर","निड","अर"],["\"मीठा\" की भाववाचक संज्ञा?","मिठास","मीठी","मीठापन","मिठाई"]],"wb":{"mis":"उपसर्ग शब्द के आगे (बे-समझ), प्रत्यय पीछे (दुकान-दार) जुड़ता है। \"आयी थी\" पूर्ण भूत, \"आ रही थी\" अपूर्ण भूत।","qz":[["\"दुकानदार\" में प्रत्यय?","दार","दुकान","कान","आर"],["\"सद्भाव\" में उपसर्ग?","सद्","भाव","स","सद्भा"],["\"प्रसन्न\" की भाववाचक संज्ञा?","प्रसन्नता","प्रसन्नी","प्रसन्नपन","प्रसाद"],["\"बूढ़ा\" की भाववाचक संज्ञा?","बुढ़ापा","बूढ़ी","बुढ़ाई","बूढ़पन"],["\"अपराधी\" का विलोम?","निरपराधी","अपराध","दोषी","पापी"],["\"ईद आयी थी\" – काल?","पूर्ण भूतकाल","अपूर्ण भूतकाल","वर्तमान काल","भविष्यत् काल"]],"pg":"13–19","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":15,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन – कविता (प्रश्न) (పుట 13)","अर्थग्राह्यता-प्रतिक्रिया (పుట 17)","अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 18)","उपसर्ग-प्रत्यय, काल, मुहावरे; परियोजना (పుట 19)"]},"tg":[["पूर्व पठन – कविता (प्रश्न) (పుట 13)",["1. पथिकों को जलती दुपहर में पेड़ (वृक्ष) से सुख व आराम मिलता है। 2. खुशबू भरे फूल हमें नव फूलों की माला (सुगंध, आनंद) देते हैं। 3. प्रकृति (पेड़, फूल) बिना माँगे हमें बहुत कुछ देती है, इसलिए हमें भी दूसरों को कुछ देना (त्याग, सेवा) सीखना चाहिए।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 17)",["अ) 1. प्रेमचंद। उनकी रचनाओं में गाँव, किसान, गरीबों का यथार्थ चित्रण, सरल-सजीव भाषा, सामाजिक समस्याएँ और मानवीय संवेदनाएँ होती हैं। 2. हामिद समझदार, त्यागी, संतोषी, आत्मसम्मानी, तर्कशील और अपनी दादी से बहुत प्रेम करने वाला बालक है; वह अपनी इच्छाओं को दबाकर दादी के लिए चिमटा लाता है।","आ) 1. नहीं (तीन पैसे थे) 2. नहीं (दादी थी) 3. हाँ 4. नहीं (चिमटा खरीदता है)","इ) 1. स्नेह 2. बैठ 3. चिमटा 4. बारह","ई) 1. श्रवण कुमार 2. श्रवण कुमार अपने अंधे माता-पिता की सेवा में सदा तत्पर रहता था; उन्हें काँवर में बिठाकर चारधाम यात्रा पर ले गया; पानी लाते समय राजा दशरथ के शब्दभेदी बाण से उसकी मृत्यु हुई; वह मातृ-पितृ भक्ति के लिए अमर है। 3. परलोक = पर + लोक / आजीवन = आ + जीवन (रेखांकित शब्द के अनुसार) 4. \"मातृ-पितृ भक्त श्रवण कुमार\""]],["अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 18)",["अ) 1. मैं भी हामिद की तरह अपनी माँ/दादी के लिए कोई उपयोगी चीज़ खरीदता, क्योंकि खिलौने जल्दी टूट जाते हैं और मिठाई खत्म हो जाती है, पर उपयोगी चीज़ से परिवार को लाभ और खुशी मिलती है। 2. हामिद अपनी दादी से बहुत प्रेम करता था; उसे दादी की जलती उँगलियों की चिंता थी; उसने अपनी इच्छाएँ त्यागकर उनके लिए चिमटा खरीदा – यह उसके त्याग, प्रेम और समझदारी को दर्शाता है।","आ) सारांश: रमज़ान के तीस रोज़ों के बाद ईद आयी। अनाथ हामिद अपनी गरीब दादी अमीना के साथ रहता था। वह तीन पैसे लेकर दोस्तों के साथ ईदगाह के मेले गया। दोस्तों ने खिलौने, मिठाइयाँ खरीदीं, झूले झूले, पर हामिद ने दादी की जलती उँगलियों को याद कर छह पैसे का चिमटा तीन पैसे में खरीदा। दोस्तों ने मज़ाक उड़ाया, पर हामिद ने तर्क से चिमटे को सबसे श्रेष्ठ सिद्ध किया। घर आने पर अमीना पहले नाराज़ हुई, पर कारण जानकर उसका क्रोध स्नेह में बदल गया और वह रोते हुए हामिद को दुआएँ देने लगी।","इ) संवाद: महमूद – \"हामिद, तुमने यह चिमटा क्यों लिया? खिलौना क्यों नहीं?\" हामिद – \"खिलौने गिरते ही टूट जाएँगे, मेरा चिमटा बहादुर है – कंधे पर रखूँ तो बंदूक, हाथ में लूँ तो फ़कीरों का चिमटा।\" मोहसिन – \"पर इससे खेलोगे कैसे?\" हामिद – \"मेरा चिमटा तुम्हारे भिश्ती को भी हरा देगा!\"","ई) बड़े-बुज़ुर्ग हमारे परिवार की नींव हैं; उन्होंने हमें पाला-पोसा, अनुभव और संस्कार दिए; वृद्धावस्था में उन्हें प्यार, सम्मान, सेवा और समय देना हमारा कर्तव्य है; उनके आशीर्वाद से जीवन सफल होता है।","भाषा की बात (अ) 1. ईद = पर्व, त्योहार – ईद खुशियों का त्योहार है; प्रभात = सवेरा, सुबह – सवेरे जल्दी उठना चाहिए; वृक्ष = पेड़, तरु – पेड़ छाया देते हैं। 2. अपराधी × निरपराधी – निरपराधी को सज़ा नहीं मिलनी चाहिए; प्रसन्न × अप्रसन्न (दुखी) – माँ आज अप्रसन्न है। 3. मिठाई – मिठाइयाँ (मेले में मिठाइयाँ बिक रही थीं); चिमटा – चिमटे (दुकान में चिमटे थे); सड़क – सड़कें (शहर की सड़कें चौड़ी हैं)।"]],["उपसर्ग-प्रत्यय, काल, मुहावरे; परियोजना (పుట 19)",["(आ) 1. बे+समझ, सद्+भाव, नि+डर 2. दुकान+दार, भड़क+ईला, गरीब+ई 3. मीठा – मिठास; प्रसन्न – प्रसन्नता; बूढ़ा – बुढ़ापा","काल: 1. हामिद चिमटा लाया / लाया है / लाया था / लाया होगा / ला रहा था। 2. हामिद दादी से (मिला) / मिला है / मिला था / मिला होगा / मिल रहा था। 3. हामिद ने चिमटा लिया / लिया है / लिया था / लिया होगा; हामिद चिमटा ले रहा था।","मुहावरे: दिल बैठ जाना (निराश होना) – परीक्षा परिणाम सुनकर उसका दिल बैठ गया; कलेजा मज़बूत करना (हिम्मत करना) – कलेजा मज़बूत करके उसने सच बोला; छाती से लगाना (प्यार से गले लगाना) – माँ ने बेटे को छाती से लगा लिया; दिल कचोटना (मन दुखी होना) – गरीब बच्चे को देखकर मेरा दिल कचोटने लगा।","परियोजना: श्रवण कुमार, \"बूढ़ी काकी\" (प्रेमचंद) जैसी कहानी ढूँढ़कर कक्षा में प्रस्तुत करना।"]]]},{"id":"hi3","no":3,"t":"हम भारतवासी","m":[7],"ty":"कविता (గీతం)","th":"देशभक्ति, विश्वबंधुत्व","by":"आर. पी. \"निशंक\" (रमेश पोखरियाल)","sum":"\"భారతీయులమైన మేము ప్రపంచాన్ని పవిత్ర ధామంగా మారుస్తాం\" అని కవి దేశభక్తి గీతం. మనసులో శ్రద్ధ, ప్రేమ చూపిస్తాం; ఎక్కువ-తక్కువ భేదాలు తొలగించి హృదయాల్లో ప్రేమ నింపుతాం; ద్వేషమనే మంచు తెర చీల్చి అమృత రసం పంచుతాం; నిరాశ పోగొట్టి విశ్వాసం జాగృతం చేస్తాం. గందరగోళంలో ఉన్నవారికి సత్యమనే దీపంతో అర్థం చేయిస్తాం; దారి తప్పినవారికి దారి చూపిస్తాం; సంతోషాల దీపాలు వెలిగిస్తాం. సత్యం, అహింస, త్యాగం, సమర్పణల తోటను పరిమళింపజేస్తాం; ప్రపంచంలోని తగాదాలు తొలగించి భూమిని స్వర్గంగా మారుస్తాం; \"విశ్వబంధుత్వం\" మూల మంత్రాన్ని ప్రపంచమంతా వ్యాపింపజేస్తాం.","pts":["కవి: रमेश पोखरियाल \"निशंक\" – ఆధునిక హిందీ సాహిత్యకారుడు; ప్రధాన విషయం దేశభక్తి.","పాఠం \"मातृभूमि के लिए\" సంగ్రహం నుండి.","రచనలు: समर्पण, नवांकुर, मुझे विधाता बनना है, तुम भी मेरे साथ चलो, जीवन पथ में, कोई मुश्किल नहीं.","విధ: గేయ కవిత (పాడదగినది); తుకాంత పదాలు (బనాయేంగే, దిఖాయేంగే, బసాయేంగే) – सामान्य भविष्यत् काल.","విలువలు: సత్యం, అహింస, త్యాగం, సమర్పణ, విశ్వబంధుత్వం, విశ్వశాంతి.","ఉపవాచకం: \"शांति की राह में\" (నిబంధం)."],"w":[["पावन","పవిత్రమైన"],["धाम","నివాసం, పుణ్యస్థలం"],["श्रद्धा","భక్తి, నమ్మకం"],["अद्भुत","ఆశ్చర్యకరమైన"],["भेद","తేడా"],["नफ़रत","ద్వేషం"],["कुहासा","పొగమంచు"],["सरसाना","వ్యాపింపజేయు, రసమయం చేయు"],["उलझन","గందరగోళం, చిక్కు"],["तथ्य","సత్యం"],["पथ","దారి"],["समर्पण","అర్పించడం"],["बगिया","చిన్న తోట"],["झगड़ा","తగాదా"],["विश्वबंधुत्व","ప్రపంచమంతా సోదరభావం"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["संधि: दो वर्णों के मेल से होने वाला परिवर्तन – हिम + आलय = हिमालय (अ + आ = आ); अति + अधिक = अत्यधिक (इ + अ = य). प्रकार: स्वर, व्यंजन, विसर्ग संधि.","संधि विच्छेद: पवन = पो + अन; पावन = पौ + अन (अयादि संधि); निराशा = निः + आशा (विसर्ग संधि).","समास: भारतवासी = भारत का वासी (तत्पुरुष); जीवनज्योत = जीवन की ज्योति (तत्पुरुष).","काल: दिखाएँगे (सामान्य भविष्य), दिखाते रहेंगे (अपूर्ण भविष्य), दिखा चुकेंगे (पूर्ण भविष्य), दिखाएँ (संभाव्य भविष्य).","वचन: खुशी – खुशियाँ – खुशियों में; बगीचा – बगीचे; भावना – भावनाएँ."]},"qa":[["हम भारतवासी दुनिया को क्या बनाएँगे?","पावन धाम।"],["नफ़रत का कुहासा तोड़कर क्या करेंगे?","अमृत रस सरसाएँगे।"],["भटके हुए लोगों के लिए क्या करेंगे?","उन्हें जीवन की राह दिखाएँगे।"],["किसकी बगिया महकाएँगे?","सत्य, अहिंसा, त्याग, समर्पण की।"],["धरती को स्वर्ग कैसे बनाएँगे?","जग के सारे झगड़े मिटाकर।"],["कौन-सा मूल मंत्र दुनिया में सरसाएँगे?","विश्वबंधुत्व का।"]],"act":"शांति के पथ पर समर्पित किसी महान व्यक्ति (गांधीजी, बुद्ध, मदर टेरेसा, नेल्सन मंडेला) के बारे में जानकारी इकट्ठा कर कक्षा में प्रस्तुत कीजिए।","kn":"\"इस संसार में वैर से वैर कभी शांत नहीं होता; प्रेम से ही वैर शांत होता है।\" – धम्मपद. \"विद्या का अंतिम लक्ष्य चरित्र-निर्माण होना चाहिए।\" – महात्मा गांधी.","qz":[["\"हम भारतवासी\" कविता के कवि?","रमेश पोखरियाल \"निशंक\"","सुमित्रानंदन पंत","दिनकर","मैथिलीशरण गुप्त"],["यह कविता किस संग्रह से ली गई है?","मातृभूमि के लिए","समर्पण","नवांकुर","चिदंबरा"],["निशंक की रचनाओं का मुख्य प्रतिपाद्य?","देशभक्ति","प्रकृति","प्रेम","हास्य"],["हम दुनिया को क्या बनाएँगे?","पावन धाम","बाज़ार","युद्धभूमि","जंगल"],["हम किसका कुहासा तोड़ेंगे?","नफ़रत का","प्रेम का","धुएँ का","बादल का"],["भटके लोगों को हम क्या दिखाएँगे?","राह","डर","धन","सपने"],["हम किसकी बगिया महकाएँगे?","सत्य, अहिंसा, त्याग, समर्पण की","फूलों की","धन की","सत्ता की"],["धरती को स्वर्ग कैसे बनाएँगे?","सारे झगड़े मिटाकर","युद्ध करके","पेड़ काटकर","धन कमाकर"],["हमारा मूल मंत्र?","विश्वबंधुत्व","स्वार्थ","युद्ध","भेदभाव"],["\"पावन\" का अर्थ?","पवित्र","हवा","सुंदर","बड़ा"],["\"मान\" का विलोम?","अपमान","निरमान","दुरमान","स्वमान"],["\"हिमालय\" का संधि विच्छेद?","हिम + आलय","हि + मालय","हिमा + लय","हिम + अलय"],["\"भारतवासी\" में समास?","तत्पुरुष","द्वंद्व","द्विगु","बहुव्रीहि"],["\"खुशी\" का बहुवचन?","खुशियाँ","खुशियों","खुशीयाँ","खुशें"]],"wb":{"mis":"पवन = पो + अन, पावन = पौ + अन (अयादि संधि) – \"प + अवन\" नहीं। \"दिखा चुकेंगे\" पूर्ण भविष्य, \"दिखाते रहेंगे\" अपूर्ण भविष्य।","qz":[["\"पावन\" संधि विच्छेद?","पौ + अन","पा + वन","पाव + अन","प + आवन"],["\"निराशा\" संधि विच्छेद?","निः + आशा","नि + राशा","निर + आशा","नी + आशा"],["\"अत्यधिक\" में कौन-सी संधि?","यण् संधि (स्वर)","विसर्ग संधि","व्यंजन संधि","दीर्घ संधि"],["\"त्याग\" का विलोम?","भोग (ग्रहण)","दान","प्रेम","सेवा"],["\"दुनिया\" का पर्याय?","विश्व, जग, संसार","धरती, आकाश","सागर, नदी","धन, दौलत"],["\"समझायेंगे\" को पूर्ण भविष्य में?","समझा चुकेंगे","समझाते रहेंगे","समझाएँ","समझाया"]],"pg":"24–28","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":26,"lb":"పాఠ్యపుస్తకం","ws":["उन्मुखीकरण (प्रश्न) (పుట 24)","कविता के पास के प्रश्न (పుట 25)","अर्थग्राह्यता-प्रतिक्रिया (పుట 26)","पद्यांश (शेष); अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 27)","संधि, समास, काल, मुहावरे; परियोजना (పుట 28)"]},"tg":[["उन्मुखीकरण (प्रश्न) (పుట 24)",["1. समुद्र में। 2. नदियाँ (समुद्र में मिलना), सभी धर्म (परमात्मा तक पहुँचना), मानव जाति और मानव धर्म – सबको एक बताया गया है। 3. सभी मनुष्य एक ही ईश्वर की संतान हैं; जाति, धर्म, रंग, भाषा के भेद मनुष्य ने बनाए हैं; हमें सबके साथ प्रेम और भाईचारे से रहना चाहिए।"]],["कविता के पास के प्रश्न (పుట 25)",["1. ऊँच-नीच का भेद मिटाने के लिए सबके साथ समान व्यवहार करेंगे, साथ खाएँगे-खेलेंगे, किसी का अपमान नहीं करेंगे, सबकी मदद करेंगे। 2. सत्य, अहिंसा, ईमानदारी और परोपकार का पथ। 3. उन्हें सही सलाह देकर, अच्छा उदाहरण बनकर, शिक्षा और प्रेरणा देकर। 4. सच बोलेंगे, हिंसा नहीं करेंगे, दूसरों के लिए अपने सुख त्यागेंगे, देश और समाज की सेवा में समर्पित रहेंगे।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 26)",["अ) 1. यह गीत मुझे बहुत अच्छा लगा, क्योंकि इसमें देशभक्ति, विश्वबंधुत्व, प्रेम और शांति का संदेश है; इसकी लय मधुर है और गाने में आनंद आता है। 2. भेदभाव मिटाकर, प्रेम और विश्वास बढ़ाकर, भटके लोगों को राह दिखाकर, सत्य-अहिंसा अपनाकर, झगड़े मिटाकर हम दुनिया को पावन धाम बना सकते हैं।","आ) मुख्य शब्द: श्रद्धा, प्रेम, अद्भुत दृश्य, सत्य, अहिंसा, त्याग, समर्पण, बगिया, झगड़े, धरती, स्वर्ग, विश्वबंधुत्व, मूल मंत्र।","इ) 1. \"जग के सारे झगड़े मिटाकर, धरती को स्वर्ग बनायेंगे।\" 2. \"भटक रहे जो जीवन पथ से, उनको राह दिखायेंगे।\" 3. \"ऊँच-नीच का भेद मिटाकर, दिल में प्यार बसायेंगे।\"","ई) 1. (इ) विश्वशांति का 2. (इ) हठीले"]],["पद्यांश (शेष); अभिव्यक्ति-सृजनात्मकता; भाषा की बात (పుట 27)",["ई) 3. (अ) आज़ादी को 4. (इ) अपमान 5. (आ) मान","अ) 1. सोच-समझकर निर्णय लेना, बड़ों की सलाह लेना, सच्चाई जानना, बुरी संगत से बचना, धैर्य रखना। 2. निराशावादी हर बात में बुराई देखता है, जल्दी हार मान लेता है, दुखी रहता है; आशावादी हर स्थिति में अच्छाई देखता है, मेहनत करता रहता है, प्रसन्न रहता है।","आ) पेड़ लगाकर, स्वच्छता रखकर, भेदभाव न करके, जरूरतमंदों की मदद करके, झगड़े न करके, सबसे प्रेम करके हम धरती को स्वर्ग बनाने में सहयोग दे सकते हैं।","इ) उदा. – कैलाश सत्यार्थी/दलाई लामा: 1. आपको शांति के कार्य की प्रेरणा कहाँ से मिली? 2. आपके सामने कौन-सी कठिनाइयाँ आईं? 3. विश्वशांति के लिए युवा क्या कर सकते हैं? 4. आपका प्रिय आदर्श व्यक्ति कौन है? 5. विद्यार्थियों के लिए आपका संदेश क्या है?","ई) सत्य से विश्वास मिलता है, अहिंसा से शांति और प्रेम बढ़ता है, त्याग से दूसरों का भला होता है – ये भावनाएँ जीवन को श्रेष्ठ, सुखी और सम्मानित बनाती हैं।","भाषा की बात (अ) 1. दुनिया = विश्व, जग, संसार – यह दुनिया बड़ी निराली है; अमृत = सुधा, पीयूष – देवताओं ने अमृत पिया; पावन = पवित्र, शुद्ध – गंगा पावन नदी है। 2. निराशा × आशा – जीवन में आशा रखो; त्याग × भोग – भोग में सुख नहीं; प्यार × नफ़रत – नफ़रत से कुछ नहीं मिलता। 3. खुशी – खुशियाँ (त्योहार खुशियाँ लाते हैं); बगीचा – बगीचे (शहर में कई बगीचे हैं); भावना – भावनाएँ (सबकी भावनाओं का आदर करो)।"]],["संधि, समास, काल, मुहावरे; परियोजना (పుట 28)",["(आ) 1. पवन = पो + अन; पावन = पौ + अन (अयादि संधि); निराशा = निः + आशा (विसर्ग संधि) 2. भारतवासी – भारत का वासी (तत्पुरुष समास); जीवनज्योत – जीवन की ज्योत (तत्पुरुष समास)","वाक्य प्रयोग: 1. खुशी – आज मुझे बहुत खुशी है। 2. खुशियाँ – दीवाली खुशियाँ लाती है। 3. खुशियों में – सब खुशियों में झूम उठे।","काल: उलझन में उलझे लोगों को तथ्य दीप समझायेंगे / समझाते रहेंगे / समझा चुकेंगे / समझाएँ।","मुहावरे: राह दिखाना (मार्गदर्शन करना) – गुरु शिष्यों को राह दिखाते हैं; दीप जलाना (आशा जगाना) – शिक्षा ज्ञान का दीप जलाती है; धरती को स्वर्ग बनाना (बहुत सुंदर/सुखी बनाना) – पेड़ लगाकर धरती को स्वर्ग बनाएँ।","परियोजना: महात्मा गांधी / गौतम बुद्ध / मदर टेरेसा के जीवन और शांति-कार्य की जानकारी इकट्ठा करना।"]]]},{"id":"hi4","no":4,"t":"कण-कण का अधिकारी","m":[7],"ty":"कविता (కవిత)","th":"श्रम का महत्व","by":"डॉ. रामधारी सिंह \"दिनकर\"","sum":"ఒక మనిషి పాపంతో (అన్యాయంగా) ధనం కూడబెడతాడు; మరొకడు \"అదృష్టం\" అనే మోసంతో దాన్ని అనుభవిస్తాడు. కానీ మానవ సమాజ భాగ్యం ఒక్కటే – అది శ్రమ, భుజబలం; దాని ముందు భూమి తలవంచుతుంది, ఆకాశం వినయంగా ఉంటుంది. చెమట (శ్రమ-జలం) చిందించినవాడిని వెనుకబడనీయకండి; ప్రకృతిని జయించిన అతనే ముందుగా సుఖం పొందాలి. ప్రకృతిలో ఉన్నదంతా మానవులందరి ధనం; దాని కణకణానికీ ప్రతి మనిషీ (శ్రమించేవాడు) అధికారి అని కవి శ్రమ గొప్పతనాన్ని, శ్రామికుల హక్కులను చాటాడు.","pts":["కవి: डॉ. रामधारी सिंह \"दिनकर\" (1908–1974) – బిహార్ ముంగేర్ జిల్లా సిమరియా గ్రామం; \"राष्ट्रकवि\".","\"उर्वशी\" కృతికి ज्ञानपीठ पुरस्कार.","రచనలు: रेणुका, कुरुक्षेत्र, रश्मिरथी, परशुराम की प्रतीक्षा, रसवंती, उर्वशी.","పాఠం \"कुरुक्षेत्र\" కావ్యం నుండి; భాష ఓజస్సు, ప్రేరణతో కూడినది.","సందేశం: శ్రమే మానవ సమాజ భాగ్యం; శ్రమించేవాడే కణకణానికీ అధికారి.","విశ్వ శ్రామిక దినోత్సవం (మే డే) – మే 1."],"w":[["मनुज","మనిషి"],["संचित करना","కూడబెట్టు"],["अर्थ","ధనం"],["भोगना","అనుభవించు"],["भाग्यवाद","అదృష్టమే అంతా అనే వాదం"],["छल","మోసం"],["भुजबल","భుజబలం"],["सम्मुख","ఎదుట"],["विनीत","వినయం గల"],["नभ-तल","ఆకాశం"],["श्रम-जल","చెమట"],["विजित","జయించబడిన"],["न्यस्त","ఉంచబడిన"],["कण-कण","ప్రతి అణువు"],["अधिकारी","హక్కుదారు"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["समास: दो या अधिक शब्दों के मेल से नया सार्थक शब्द, विभक्ति चिह्नों का लोप – राजपुत्र (राजा का पुत्र), देशभक्त (देश का भक्त). छह प्रकार: तत्पुरुष, कर्मधारय, द्वंद्व, अव्ययीभाव, द्विगु, बहुव्रीहि.","संधि विच्छेद: यद्यपि = यदि + अपि; पर्यावरण = परि + आवरण (यण् संधि).","उपसर्ग: अ+भाग्य, दुर्+भाग्य, सु+भाग्य. प्रत्यय: प्रकृति+इक, अधिकार+ई, भाग्य+वान.","संयुक्त क्रिया: जाने दो, पाने दो, बढ़ने दो. संख्यावाचक: एक–पहला–प्रथम, दो–दूसरा–द्वितीय."]},"qa":[["भाग्यवाद का छल क्या है?","पाप से धन कमाने वाले का धन दूसरा \"भाग्य\" के नाम पर भोगता है – यही छल है।"],["नर-समाज का भाग्य क्या है?","श्रम और भुजबल।"],["श्रम के सम्मुख कौन झुके हैं?","पृथ्वी और विनीत नभ-तल।"],["सबसे पहले सुख पाने का अधिकार किसे है?","जिसने श्रम-जल (पसीना) दिया, यानी श्रमिक को।"],["मनुज मात्र का धन क्या है?","प्रकृति में जो कुछ न्यस्त है।"],["कण-कण का अधिकारी कौन है?","जन-जन (मेहनत करने वाला हर मनुष्य)।"]],"act":"विश्व श्रम दिवस (मई दिवस – 1 मई) के बारे में जानकारी इकट्ठा कीजिए और कक्षा में प्रदर्शन कीजिए।","kn":"\"श्रम ईश्वर की उपासना है।\" – कारलाइल. \"स्वप्न साकार करना है तो चिंता छोड़कर कुछ श्रम करो।\" – दिनकर.","qz":[["\"कण-कण का अधिकारी\" के कवि?","रामधारी सिंह दिनकर","सुमित्रानंदन पंत","निशंक","रहीम"],["दिनकर को क्या कहा जाता है?","राष्ट्रकवि","प्रकृति कवि","उपन्यास सम्राट","छायावादी कवि"],["यह कविता किस काव्य से ली गई है?","कुरुक्षेत्र","रश्मिरथी","उर्वशी","रेणुका"],["दिनकर को ज्ञानपीठ पुरस्कार किस कृति पर मिला?","उर्वशी","कुरुक्षेत्र","रसवंती","रश्मिरथी"],["दिनकर का जन्म कहाँ हुआ?","सिमरिया (बिहार)","कौसानी","लमही","इलाहाबाद"],["एक मनुज अर्थ किसके बल से संचित करता है?","पाप के","श्रम के","भाग्य के","ज्ञान के"],["दूसरा उसे किसके छल से भोगता है?","भाग्यवाद के","पाप के","श्रम के","धन के"],["नर-समाज का भाग्य क्या है?","श्रम, भुजबल","धन","भाग्य","राजा"],["\"श्रम-जल\" का अर्थ?","पसीना","वर्षा","नदी","आँसू"],["कण-कण का अधिकारी कौन?","जन-जन","राजा","धनी","भाग्यवान"],["\"मनुज\" का अर्थ?","मनुष्य","मन","मनु","मन की इच्छा"],["\"यद्यपि\" का संधि विच्छेद?","यदि + अपि","यद् + यपि","यद्य + पि","य + द्यपि"],["\"दुर्भाग्य\" में उपसर्ग?","दुर्","दु","भाग्य","दुर्भा"],["\"भाग्यवान\" में प्रत्यय?","वान","भाग्य","आन","वान्य"]],"wb":{"mis":"उपसर्ग शब्द के पहले (अ-, दुर्-, सु-), प्रत्यय बाद में (-इक, -ई, -वान)। \"श्रम-जल\" तत्पुरुष (श्रम का जल), \"भुजबल\" तत्पुरुष (भुजा का बल)।","qz":[["\"पर्यावरण\" का संधि विच्छेद?","परि + आवरण","पर्या + वरण","पर + यावरण","परी + आवरण"],["\"भुजबल\" में समास?","तत्पुरुष (भुजा का बल)","द्वंद्व","द्विगु","अव्ययीभाव"],["\"पाप\" का विलोम?","पुण्य","धर्म","सुख","दान"],["\"मनुष्य\" की भाववाचक संज्ञा?","मनुष्यता","मनुष्यपन","मानव","मनुष्यी"],["\"मज़दूर मेहनत करता है\" – बहुवचन?","मज़दूर मेहनत करते हैं","मज़दूरों मेहनत करता है","मज़दूरें मेहनत करती हैं","मज़दूर मेहनत करती है"],["\"प्राकृतिक\" में प्रत्यय?","इक","कृति","प्रा","तिक"]],"pg":"32–36","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":34,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 32)","कविता के पास के प्रश्न (పుట 33)","अर्थग्राह्यता-प्रतिक्रिया; अभिव्यक्ति (పుట 34)","सृजनात्मक कार्य; भाषा की बात (పుట 35)","शब्द रचना, वाक्य परिवर्तन; परियोजना (పుట 36)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 32)",["1. गाँधीजी सूत कातते, कपड़ा बुनते, अनाज के कंकर चुनते और चक्की पीसते थे। 2. श्रम (मेहनत)। 3. श्रम से ही भोजन, घर, धन, सफलता और सम्मान मिलता है; श्रम से शरीर स्वस्थ और मन प्रसन्न रहता है।"]],["कविता के पास के प्रश्न (పుట 33)",["1. एक व्यक्ति पाप से धन जमा करता है और दूसरा उसे \"भाग्य\" के नाम पर भोगता है – यही भाग्यवाद का छल है। 2. श्रम और भुजबल। 3. पृथ्वी और विनीत नभ-तल (आकाश)। 4. श्रमिक (मज़दूर) ने। 5. प्रकृति में जो कुछ है, वह मनुष्य मात्र का धन है। 6. जन-जन (मेहनत करने वाला हर व्यक्ति)।"]],["अर्थग्राह्यता-प्रतिक्रिया; अभिव्यक्ति (పుట 34)",["अ) 1. मैं कर्म को श्रेष्ठ मानता हूँ, क्योंकि कर्म से ही भाग्य बनता है; केवल भाग्य के भरोसे बैठने से कुछ नहीं मिलता। 2. श्रम से शिक्षा, धन, सम्मान, स्वास्थ्य, सफलता और देश की उन्नति हासिल कर सकते हैं।","आ) 1. डॉ. रामधारी सिंह \"दिनकर\" 2. \"कुरुक्षेत्र\" 3. जिसने श्रम-जल (पसीना) दिया, उस श्रमिक को 4. जन-जन को, क्योंकि प्रकृति में जो कुछ है वह मनुष्य मात्र का धन है और श्रम से ही उसका उपयोग होता है।","इ) 1. \"जिसके सम्मुख झुकी हुई पृथ्वी, विनीत नभ-तल है।\" 2. \"जो कुछ न्यस्त प्रकृति में है, वह मनुज मात्र का धन है।\"","ई) 1. लगातार कदम बढ़ाकर, कर्म करके, लक्ष्य पर नज़र रखकर 2. जब हम अपनी निगाहें लक्ष्य पर रखते हैं 3. \"कर्म से भाग्य\" / \"बढ़ते चलो\"","अभि. अ) 1. श्रमिक ही खेत, कारखाने, सड़कें, भवन बनाकर समाज को सब कुछ देता है, पर उसे उसका हक नहीं मिलता; इसलिए कवि उसे सबसे पहले सुख देने और आगे रखने की बात करता है। 2. श्रम करने वाला सही है; अनुचित तरीके से कमाया धन पाप है, उससे सम्मान और शांति नहीं मिलती; मेहनत की कमाई पवित्र होती है।","आ) कवि कहते हैं कि मज़दूर का पसीना ही समाज का भाग्य है; उसके सामने धरती-आकाश झुकते हैं; उसे पीछे नहीं रहने देना चाहिए; प्रकृति को जीतने वाले मज़दूर को सबसे पहले सुख मिलना चाहिए; प्रकृति के कण-कण पर हर मेहनतकश का अधिकार है।"]],["सृजनात्मक कार्य; भाषा की बात (పుట 35)",["इ) उदा. घटना: एक गरीब किसान ने सूखे खेत में कुआँ खोदकर फसल उगाई। मुख्यांश: गरीब किसान, सूखा खेत, कुआँ, मेहनत, फसल। मूल शब्द: किसान, मेहनत, फसल। कविता: \"किसान ने खोदा कुआँ, / बहा पसीना जैसे धुआँ, / सूखी धरती मुस्काई, / मेहनत से फसल लहराई।\" संदेश: मेहनत से ही सफलता मिलती है। नारे: \"मेहनत करो, आगे बढ़ो\"; \"श्रम ही पूजा है\"।","ई) श्रम ही सफलता का मार्ग है; मेहनत करने वाला कभी नहीं हारता; भाग्य भी कर्म से बनता है; किसान, मज़दूर, वैज्ञानिक, विद्यार्थी – सब मेहनत से ही आगे बढ़ते हैं; गांधीजी, कलाम जैसे महापुरुष श्रम से महान बने।","भाषा की बात (अ) 1. जल = पानी, नीर – पानी जीवन है; पृथ्वी = धरती, भूमि – धरती हमारी माँ है; धन = दौलत, संपत्ति – धन का सदुपयोग करो। 2. पाप × पुण्य – पुण्य कार्य करो; सुख × दुख – दुख में धैर्य रखो; भाग्य × दुर्भाग्य – आलस्य दुर्भाग्य लाता है। 3. देशभक्ति जन-जन में है; कण-कण में भगवान है। 4. मज़दूर मेहनत करते हैं। 5. मनुष्य – मनुष्यता; मज़दूर – मज़दूरी।","(आ) 1. अधिकार – संज्ञा (हक), अधिकारी – हक वाला व्यक्ति (ई प्रत्यय); भाग्य – संज्ञा, भाग्यवान – विशेषण (वान प्रत्यय)। 2. यद्यपि = यदि + अपि; पर्यावरण = परि + आवरण 3. श्रम-जल (श्रम का जल), नभ-तल (नभ का तल), भुजबल (भुजा का बल) – तत्पुरुष समास 4. एक – संख्यावाचक विशेषण; मनुज – संज्ञा, पुल्लिंग, एकवचन, कर्ता; संचित करता है – सकर्मक क्रिया, वर्तमान काल; अर्थ – संज्ञा, कर्म; पाप – संज्ञा; दूसरा – सर्वनाम/विशेषण; भाग्यवाद – संज्ञा 5. जिसने – कर्ता कारक (ने); उसे – कर्म कारक (को)"]],["शब्द रचना, वाक्य परिवर्तन; परियोजना (పుట 36)",["इ) 1. जाने दो, पाने दो, बढ़ने दो – \"देना\" सहायक क्रिया से अनुमति का भाव। 2. एक – मूल संख्या, पहला/प्रथम – क्रम संख्या; दो – मूल संख्या, दूसरा/द्वितीय – क्रम संख्या। 3. प्रकृति+इक, अधिकार+ई, भाग्य+वान (प्रत्यय) 4. अ+भाग्य, दुर्+भाग्य, सु+भाग्य (उपसर्ग) 5. स्त्रियाँ श्रमिकाओं के रूप में मेहनत करती हैं।","ई) 1. प्रकृति में न्यस्त सब कुछ मनुज मात्र का धन है। 2. मेहनत करने वाला ही कण-कण का अधिकारी है। 3. परोपकार करने वाला ही परोपकारी कहलाता है।","परियोजना: 1 मई – अंतर्राष्ट्रीय श्रमिक दिवस; 1886 शिकागो में 8 घंटे काम की माँग; भारत में 1923 से (चेन्नई) मनाया जाता है।"]]]},{"id":"hi5","no":5,"t":"लोकगीत","m":[7],"ty":"निबंध (వ్యాసం)","th":"भारतीय लोकगीत, संस्कृति","by":"भगवतशरण उपाध्याय","sum":"జానపద గీతాలు (లోకగీత్) నేరుగా ప్రజల సంగీతం – శాస్త్రీయ సంగీతం కంటే సరళంగా, తాజాగా, జనాదరణతో ఉంటాయి; వీటికి సాధన అవసరం లేదు; పండుగల్లో, ప్రత్యేక సందర్భాల్లో ఢోలక్, ఝాంఝ్, కర్తాల్, బాంసురి సాయంతో పాడతారు. ఒకప్పుడు వీటిని చిన్నచూపు చూశారు, ఇప్పుడు సేకరణలు ప్రచురితమవుతున్నాయి. ఆదివాసుల (గోండ్, భిల్, సంతాల్) గీతాలు ఓజస్సుతో, పెద్ద బృందాలుగా పాడతారు; పర్వత ప్రాంతాల గీతాలను \"పహాడీ\" అంటారు. నిజమైన లోకగీతాలు గ్రామాల్లోనే – చైతా, కజరీ, బారహమాసా, సావన్ (UP/బిహార్), బాఉల్, భటియాలీ (బెంగాల్), హీర్-రాంఝా, సోహనీ-మహీవాల్ (పంజాబ్), ఢోలా-మారూ (రాజస్థాన్). భోజ్‌పురిలో \"బిదేసియా\", ఆల్హా (జగనిక్ – ఆల్హా-ఊదల్ వీరత్వం) ప్రసిద్ధం. స్త్రీల గీతాలు అనంతం – సోహర్, బానీ, సెహరా, పెళ్ళి, పండుగ గీతాలు; బృందాలుగా పాడతారు; గుజరాత్ \"గర్బా\". ఉల్లాసమైన గ్రామీణ జీవితమే ఈ గీతాలకు మూలం.","pts":["రచయిత: भगवतशरण उपाध्याय (1910–1982) – కథ, కవిత, రిపోర్తాజ్, నిబంధం, విమర్శ, చరిత్ర రంగాల్లో ముద్ర.","రచనలు: विश्व साहित्य की रूपरेखा, कालिदास का भारत, ठूँठा आम, गंगा गोदावरी.","విధ: निबंध – \"బంధించడం\"; అందమైన పద్ధతిలో భావాల ప్రదర్శన. \"గద్యం కవులకు గీటురాయి అయితే నిబంధం గద్యానికి గీటురాయి\" – రామచంద్ర శుక్ల.","లోకగీతాల రకాలు: ఆదివాసీ, పహాడీ, చైతా, కజరీ, బారహమాసా, సావన్, బాఉల్, భటియాలీ, బిదేసియా, ఆల్హా, సోహర్, బానీ, సెహరా, గర్బా.","ఆల్హా – చందేల్ రాజుల ఆస్థాన కవి జగనిక్; బిదేసియా – భోజ్‌పురి (విరహ రసం).","మైథిల కోకిల విద్యాపతి గీతాలు తూర్పు ప్రాంతంలో."],"w":[["लोच","మెత్తదనం, వశ్యత"],["ताज़गी","తాజాదనం"],["साधना","అభ్యాసం"],["हेय","తక్కువ, చిన్నచూపు"],["उपेक्षा","నిర్లక్ష్యం"],["ओजस्वी","శక్తిమంతమైన"],["देहात","గ్రామం"],["आह्लादकर","ఆనందకరమైన"],["विरह","ఎడబాటు"],["ह्रास","క్షీణత"],["बखान","వర్ణన, పొగడ్త"],["अनंत","అంతులేని"],["उल्लसित","ఉల్లాసమైన"],["उद्दाम","ఉత్సాహభరితమైన"],["परदेशी","విదేశీయుడు"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["कर्मवाच्य: \"स्त्रियाँ गीत गाती हैं\" → \"स्त्रियों के द्वारा गीत गाये जाते हैं / गाये जा रहे हैं / गाये जा रहे होंगे\".","वाक्य परिवर्तन: \"लोकगीत गाँव का संगीत है\" → प्रश्नवाचक: \"क्या लोकगीत गाँव का संगीत है?\"; बलात्मक: \"लोकगीत गाँव का संगीत है न!\".","समोच्चरित भिन्नार्थक शब्द: उपेक्षा (నిర్లక్ష్యం) – अपेक्षा (ఆశ); कृतज्ञ (కృతజ్ఞుడు) – कृतघ्न (కృతఘ్నుడు); बहार (వసంతం) – बाहर (బయట); दावत (విందు) – दवात (సిరాబుడ్డి).","अनेकार्थी: पर (కానీ / రెక్కలు); हल (నాగలి / పరిష్కారం).","\"इक\" प्रत्यय: धर्म–धार्मिक, मास–मासिक, दिन–दैनिक, उत्साह–उत्साहिक."]},"qa":[["लोकगीत किसके संगीत हैं?","सीधे जनता के – घर, गाँव और नगर की जनता के।"],["लोकगीत किन वाद्यों की मदद से गाये जाते हैं?","ढोलक, झाँझ, करताल, बाँसुरी आदि।"],["\"पहाड़ी\" किसे कहा जाता है?","गढ़वाल, किन्नौर, काँगड़ा आदि पहाड़ी प्रदेशों के गीतों को।"],["बाउल और भटियाली कहाँ के लोकगीत हैं?","बंगाल के।"],["आल्हा का आरंभ किसने किया?","चंदेल राजाओं के राजकवि जगनिक ने।"],["गुजरात का दलीय गायन?","गरबा।"]],"act":"भारतेंदु हरिश्चंद्र के प्रहसन \"अंधेर नगरी\" (जिस पर सोहनलाल द्विवेदी ने कविता रची) से संबंधित सामग्री का संग्रह कर कक्षा में प्रस्तुत कीजिए; अपने क्षेत्र के लोकगीत इकट्ठा कीजिए।","kn":"\"मधुर संगीत आत्मा के ताप को शांत कर सकता है।\" – महात्मा गांधी. \"संगीत का दूसरा नाम संजीवनी है।\" – शेख सादी. पठन हेतु: \"उलझन\".","qz":[["\"लोकगीत\" निबंध के लेखक?","भगवतशरण उपाध्याय","प्रेमचंद","दिनकर","काका कालेलकर"],["\"निबंध\" का अर्थ?","बाँधना","लिखना","गाना","बोलना"],["लोकगीत किसके संगीत हैं?","जनता के","राजाओं के","पंडितों के","विदेशियों के"],["लोकगीत के लिए किसकी ज़रूरत नहीं होती?","साधना की","जनता की","वाद्यों की","त्योहारों की"],["बाउल और भटियाली किस प्रदेश के लोकगीत हैं?","बंगाल","पंजाब","राजस्थान","बिहार"],["हीर-राँझा किस भाषा के गीत?","पंजाबी","भोजपुरी","राजस्थानी","मैथिली"],["\"बिदेसिया\" किस बोली में प्रसिद्ध है?","भोजपुरी","अवधी","ब्रज","मैथिली"],["आल्हा का आरंभ किसने किया?","जगनिक","विद्यापति","कालिदास","भारतेंदु"],["आल्हा में किसकी वीरता का बखान?","आल्हा-ऊदल","हीर-राँझा","ढोला-मारू","सोहनी-महीवाल"],["गुजरात का दलीय गायन?","गरबा","कजरी","चैता","बिरहा"],["\"मैथिल-कोकिल\" किसे कहा गया है?","विद्यापति","कबीर","सूरदास","तुलसीदास"],["\"उपेक्षा\" का अर्थ?","अनदेखी, निरादर","आशा","इच्छा","प्रतीक्षा"],["\"कृतज्ञ\" का विलोम?","कृतघ्न","अज्ञ","सुज्ञ","विज्ञ"],["\"दिन\" + इक = ?","दैनिक","दिनिक","दीनिक","दिनक"]],"wb":{"mis":"\"दावत\" = భోజనానికి ఆహ్వానం, \"दवात\" = సిరాబుడ్డి; \"बहार\" = వసంతం, \"बाहर\" = బయట. కర్మవాచ్యంలో \"के द्वारा\" + \"जाता/जाते\".","qz":[["\"स्त्रियाँ गीत गाती हैं\" – कर्मवाच्य?","स्त्रियों के द्वारा गीत गाये जाते हैं","स्त्रियों ने गीत गाया","गीत स्त्रियाँ गाती","गीत गा रही हैं स्त्रियाँ"],["\"दवात\" का अर्थ?","स्याही की शीशी","भोज","दवा","दावा"],["\"परदेशी\" का विलोम?","स्वदेशी","विदेशी","प्रवासी","देहाती"],["\"सजीव\" का विलोम?","निर्जीव","अजीव","जीवित","सजीला"],["\"गायक\" का स्त्रीलिंग?","गायिका","गायकी","गायकिन","गायनी"],["\"लोकगीत गाँव का संगीत है\" – प्रश्नवाचक?","क्या लोकगीत गाँव का संगीत है?","लोकगीत गाँव का संगीत है न!","लोकगीत गाँव का संगीत नहीं है","लोकगीत गाँव का संगीत होगा"]],"pg":"37–44","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":39,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 37)","पाठ के पास के प्रश्न (పుట 38)","पाठ के पास के प्रश्न (शेष) (పుట 40)","अर्थग्राह्यता-प्रतिक्रिया (పుట 41)","गद्यांश, लोकगीत; अभिव्यक्ति (పుట 42)","अभिव्यक्ति (शेष); भाषा की बात (పుట 43)","वाच्य, वाक्य परिवर्तन; परियोजना (పుట 44)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 37)",["1. मेहंदी (गहरी लाली)। 2. लोकगीत। 3. विवाह, जन्म, त्योहार, ऋतु (सावन, होली), खेती-कटाई, मेले आदि संदर्भों में लोकगीत गाये जाते हैं।"]],["पाठ के पास के प्रश्न (పుట 38)",["1. लोकगीत सीधे जनता के संगीत हैं, इनके लिए साधना की ज़रूरत नहीं, त्योहारों-अवसरों पर गाये जाते हैं। 2. लोकगीत जनता के संगीत हैं, ढोलक-बाँसुरी आदि के साथ गाये जाते हैं; संगीत से ही लोकगीत में जान आती है। 3. गढ़वाल, किन्नौर, काँगड़ा आदि पहाड़ी प्रदेशों के गीतों को।"]],["पाठ के पास के प्रश्न (शेष) (పుట 40)",["4. वास्तविक लोकगीत गाँवों-देहातों में होते हैं, जनता से सीधे जुड़े, जानदार, रोज़मर्रा के जीवन से विषय लेने वाले। 5. बारहमासा में बारह महीनों का वर्णन होता है; इसे पुरुष और स्त्रियाँ दोनों गाते हैं; यह उत्तर प्रदेश-बिहार में प्रसिद्ध है। 6. भोजपुरी का लोकगीत; परदेश गए प्रेमी की याद, विरह रस; गाने वालों के समूह देहात में घूम-घूमकर गाते हैं।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 41)",["अ) 1. गाँव के लोग खेती-मज़दूरी से थककर त्योहारों, शादियों, ऋतुओं में मिलकर लोकगीत गाते-नाचते हैं, जिससे थकान दूर होती है, आनंद मिलता है और आपसी मेल बढ़ता है। 2. उदा. (तेलुगु लोकगीत) \"चंदमामा रावे, जाबिल्ली रावे…\" या हिंदी: \"सावन का महीना पवन करे सोर…\"","आ) 1. लोकगीत सीधे जनता के संगीत हैं। 2. गाँव के गीतों के वास्तव में अनंत प्रकार हैं। 3. स्त्रियाँ ढोलक की मदद से गाती हैं।"]],["गद्यांश, लोकगीत; अभिव्यक्ति (పుట 42)",["इ) मुख्य शब्द: गीत, गाँव, अनंत प्रकार, जीवन, इठलाना, आनंद, स्रोत, उद्दाम जीवन, प्रतीक।","ई) 1. बर्फ़ी का 2. बजाज (कपड़े) की दुकान पर 3. बीड़ा (पान) का 4. मुनिया (मन/चंचल आत्मा) हर सुख का रस लेती है – संसार के मोह-माया का आकर्षण।","अभि. अ) 1. लोकगीतों की परिभाषा, शास्त्रीय संगीत से अंतर, वाद्य, प्रकार (आदिवासी, पहाड़ी, चैता, कजरी, बारहमासा, बाउल, बिदेसिया, आल्हा), स्त्रियों के गीत, गरबा आदि – बिंदु: (1) परिचय (2) प्रकार (3) क्षेत्रीय रूप (4) स्त्री-गीत (5) महत्व। 2. शहरीकरण, सिनेमा, टीवी, मोबाइल के कारण लोकगीत कम हो रहे हैं; नई पीढ़ी इन्हें भूल रही है; गाने वालों की संख्या घट रही है; लोक-संस्कृति खतरे में है।"]],["अभिव्यक्ति (शेष); भाषा की बात (పుట 43)",["आ) सारांश: लोकगीत सीधे जनता के संगीत हैं, जो ताज़गी और लोकप्रियता में शास्त्रीय संगीत से भिन्न हैं। पहले इनकी उपेक्षा हुई, अब इनके संग्रह छप रहे हैं। आदिवासी, पहाड़ी, चैता, कजरी, बारहमासा, बाउल, भटियाली, हीर-राँझा, बिदेसिया, आल्हा जैसे अनेक प्रकार हैं। स्त्रियों के गीत अनंत हैं – सोहर, बानी, सेहरा, विवाह के गीत; वे दल बाँधकर गाती हैं; गुजरात का गरबा प्रसिद्ध है। उल्लासमय ग्रामीण जीवन ही इन गीतों का स्रोत है।","इ) उदा. तेलुगु लोकगीत का हिंदी अनुवाद: \"आओ चंदा मामा, आओ प्यारे चाँद, / पहाड़ पर चढ़कर आओ, / सोने की थाली में खीर लाओ, / मेरे मुन्ने के मुँह में डालो।\"","ई) लोकगीतों में किसानों का श्रम, बेटी की विदाई का दुख (अप्पगिंत गीत), परदेशी प्रिय का विरह (बिदेसिया), माँ की लोरी, ऋतुओं का आनंद, देवी-देवताओं की भक्ति, वीरों की गाथा – ये सब ग्रामीण जनता की मार्मिक भावनाएँ हैं।","भाषा की बात (अ) 1. साधना = तपस्या, अभ्यास – संगीत साधना से आता है; त्योहार = पर्व, उत्सव – दीपावली बड़ा पर्व है; देहात = गाँव, ग्राम – मेरा गाँव सुंदर है। 2. सजीव × निर्जीव – पत्थर निर्जीव है; परदेशी × स्वदेशी – स्वदेशी वस्तुएँ अपनाओ; शास्त्रीय × लोक/अशास्त्रीय – लोकसंगीत सरल है। 3. ये आदिवासियों के संगीत हैं।","(आ) 1. लोकसभा, लोकमत (लोकनृत्य, लोककथा) 2. गायक – गायिका (गायिका मधुर गाती है); कवि – कवयित्री (महादेवी वर्मा कवयित्री थीं); लेखक – लेखिका (वह प्रसिद्ध लेखिका है) 3. धर्म – धार्मिक (यह धार्मिक स्थल है); मास – मासिक (मासिक पत्रिका); दिन – दैनिक (दैनिक समाचार पत्र); उत्साह – उत्साहिक/उत्साही (उत्साही बालक)","(इ) 1. उपेक्षा = अनदेखी; अपेक्षा = आशा 2. कृतज्ञ = उपकार मानने वाला; कृतघ्न = उपकार न मानने वाला 3. बहार = वसंत/रौनक; बाहर = भीतर का उलटा 4. दावत = भोज; दवात = स्याही की शीशी 5. पर = लेकिन / पंख 6. हल = खेत जोतने का औज़ार / समाधान"]],["वाच्य, वाक्य परिवर्तन; परियोजना (పుట 44)",["ई) 1. लोगों के द्वारा लोकगीत गाया जाता है / गाया जा रहा है / गाया जा रहा होगा। 2. अध्यापक के द्वारा पाठ पढ़ाया जाता है / पढ़ाया जा रहा है / पढ़ाया जा रहा होगा।","(2) 1. क्या स्त्रियाँ ढोलक की मदद से गाती हैं? / स्त्रियाँ ढोलक की मदद से गाती हैं न! 2. क्या लोकगीत के कई प्रकार हैं? / लोकगीत के कई प्रकार हैं न!","परियोजना: भारतेंदु हरिश्चंद्र का प्रहसन \"अंधेर नगरी\" – \"अंधेर नगरी चौपट राजा, टके सेर भाजी टके सेर खाजा\" – कविता/कहानी संग्रह कर कक्षा में प्रस्तुत।"]]]},{"id":"hi6","no":6,"t":"अंतर्राष्ट्रीय स्तर पर हिंदी","m":[8],"ty":"पत्र (లేఖ)","th":"हिंदी का महत्व","by":"संकलित","sum":"విజయవాడ నుండి ఒక మిత్రుడు కడప జిల్లా పరిషత్ పాఠశాలలో పదో తరగతి చదువుతున్న మిత్రుడు ఎం. ఇమాన్యుయేలుకు రాసిన లేఖ ఇది – హిందీ నేర్చుకోవడం వల్ల లాభాలు వివరిస్తాడు. స్వాతంత్ర్య సంగ్రామంలో దేశాన్ని ఏకం చేయడానికి ఒక భాష అవసరమైంది – ఆ పని హిందీతోనే సాధ్యమైంది; అందుకే అది \"భారతీయ\" భాష. రాజ్యాంగం అనుచ్ఛేదం 343(1) ప్రకారం 14 సెప్టెంబర్ 1949 న హిందీకి రాజభాష గౌరవం దక్కింది; ఏటా సెప్టెంబర్ 14 హిందీ దినోత్సవం, జనవరి 10 విశ్వ హిందీ దినోత్సవం. బంగ్లాదేశ్, నేపాల్, మారిషస్, ఫిజీ, సూరినామ్, ట్రినిడాడ్, దక్షిణాఫ్రికా, అమెరికా, ఇంగ్లాండ్, జర్మనీ, జపాన్ మొదలైన దేశాల్లో హిందీకి గిరాకీ పెరుగుతోంది; 150 కి పైగా విశ్వవిద్యాలయాల్లో హిందీ కోర్సులు ఉన్నాయి. బ్యాంకులు, మీడియా, సినిమా, అనువాదం వంటి రంగాల్లో ఉపాధికి హిందీ ముఖ్య ఆధారం. కాబట్టి ముందు చదువులకు హిందీ తీసుకోవడం లాభదాయకం అని సలహా.","pts":["విధ: पत्र (లేఖ) – గద్యంలో ముఖ్య విధ; ప్రేషకుడు (పంపేవాడు) ప్రాపకుడి (అందుకునేవాడి) పేరుతో రాస్తాడు; ఇది అనౌపచారిక (వ్యక్తిగత) లేఖ.","లేఖ విజయవాడ నుండి; చిరునామా: ఎం. ఇమాన్యుయేలు, పదో తరగతి, జిల్లా పరిషత్ ఉన్నత పాఠశాల, జయనగర్ కాలనీ, కడప.","రాజ్యాంగం అనుచ్ఛేదం 343(1) – 14 సెప్టెంబర్ 1949 న హిందీకి రాజభాష హోదా; హిందీ దివస్ – సెప్టెంబర్ 14; విశ్వ హిందీ దివస్ – జనవరి 10.","కేంద్రీయ హిందీ సంస్థాన్ – హిందీ బోధన, శిక్షణ.","హిందీ వెబ్‌సైట్లు: rajbhasha.nic.in, ildc.gov.in, bhashaindia.com.","సమాసం: तत्पुरुष (राजकुमार, विद्यालय, नेत्रहीन), कर्मधारय (पीतांबर, नीलकमल, नीलकंठ, महादेव)."],"w":[["स्तर","స్థాయి"],["सकुशल","క్షేమంగా"],["जिज्ञासा","తెలుసుకోవాలనే కోరిక"],["समाधान","పరిష్కారం"],["सूत्र","దారం"],["साध्य","సాధ్యం"],["राजभाषा","అధికార భాష"],["अनुच्छेद","అధికరణం (ఆర్టికల్)"],["गौरवान्वित","గౌరవించబడిన"],["माँग","గిరాకీ"],["रोज़गार","ఉపాధి"],["संकल्प","దృఢ నిశ్చయం"],["अद्वितीय","సాటిలేని"],["प्रेषक","పంపేవాడు"],["प्रापक","అందుకునేవాడు"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["तत्पुरुष समास: बीच का कारक चिह्न लुप्त – राजा का कुमार = राजकुमार, तुलसी से कृत = तुलसीकृत, विद्या के लिए आलय = विद्यालय, नेत्र से हीन = नेत्रहीन, दान में वीर = दानवीर.","कर्मधारय समास: पहला पद विशेषण/उपमान – पीत है जो अंबर = पीतांबर, नील है जो कमल = नीलकमल, महान है जो देव = महादेव, परम है जो आनंद = परमानंद.","उपसर्ग: स+कुशल, अनु+क्रम, अन्+उचित. प्रत्यय: वर्ष+इक, खुश+ई, भारत+ईय.","मिश्र वाक्य: \"मुझे पूरा विश्वास है कि तुम हिंदी से अपना भविष्य बनाओगे\" – प्रधान उपवाक्य + आश्रित उपवाक्य (कि, जो…वह)."]},"qa":[["हिंदी को राजभाषा कब घोषित किया गया?","14 सितंबर 1949 को, संविधान के अनुच्छेद 343(1) के तहत।"],["हिंदी दिवस कब मनाया जाता है?","हर वर्ष 14 सितंबर को।"],["विश्व हिंदी दिवस कब है?","10 जनवरी को।"],["पत्र किसे लिखा गया है?","एम. इमानुएलु, दसवीं कक्षा, जिला परिषद उन्नत पाठशाला, कड़पा।"],["हिंदी से रोज़गार के कौन-से क्षेत्र हैं?","बैंक, मीडिया, फ़िल्म, अनुवाद, शिक्षण, राजभाषा अधिकारी आदि।"],["हिंदी शिक्षण में कौन-सी संस्था योगदान दे रही है?","केंद्रीय हिंदी संस्थान।"]],"act":"इस पुस्तक के पहले से पाँचवें पाठ तक आए चित्रों में से किसी एक चित्र का चयन करके उसके बारे में पाँच वाक्य लिखिए और कक्षा में प्रस्तुत कीजिए।","kn":"\"राष्ट्रभाषा की जगह एक हिंदी ही ले सकती है।\" – महात्मा गांधी. उपवाचक: \"दो कलाकार\" (मन्नू भंडारी).","qz":[["यह पाठ किस विधा में है?","पत्र","कहानी","कविता","एकांकी"],["पत्र कहाँ से लिखा गया है?","विजयवाड़ा","कड़पा","हैदराबाद","दिल्ली"],["पत्र किसे लिखा गया?","एम. इमानुएलु","कृषित","हामिद","श्रवण"],["हिंदी को राजभाषा किस अनुच्छेद के तहत बनाया गया?","343(1)","370","51","21"],["हिंदी दिवस कब मनाया जाता है?","14 सितंबर","10 जनवरी","26 जनवरी","2 अक्टूबर"],["विश्व हिंदी दिवस?","10 जनवरी","14 सितंबर","15 अगस्त","5 सितंबर"],["हिंदी को राजभाषा किस वर्ष घोषित किया गया?","1949","1947","1950","1952"],["स्वतंत्रता संग्राम में देश को किसने एकता के सूत्र में बाँधा?","हिंदी ने","अंग्रेज़ी ने","संस्कृत ने","उर्दू ने"],["हिंदी शिक्षण प्रशिक्षण में योगदान देने वाली संस्था?","केंद्रीय हिंदी संस्थान","साहित्य अकादमी","NCERT","UGC"],["विश्व में लगभग कितने विश्वविद्यालयों में हिंदी कोर्स हैं?","डेढ़ सौ से अधिक","दस","पचास","हज़ार"],["\"राजकुमार\" में समास?","तत्पुरुष","कर्मधारय","द्वंद्व","द्विगु"],["\"नीलकमल\" में समास?","कर्मधारय","तत्पुरुष","द्वंद्व","अव्ययीभाव"],["\"सकुशल\" में उपसर्ग?","स","सकु","कुशल","शल"],["\"भारतीय\" में प्रत्यय?","ईय","भारत","तीय","य"]],"wb":{"mis":"तत्पुरुष में कारक चिह्न (का, से, के लिए, में) लुप्त होता है; कर्मधारय में विशेषण-विशेष्य संबंध (\"है जो\")। \"अनुचित\" में उपसर्ग \"अन्\" है, \"अनु\" नहीं।","qz":[["\"विद्यालय\" का विग्रह?","विद्या के लिए आलय","विद्या और आलय","विद्या है जो आलय","विद्या में आलय"],["\"पीतांबर\" का विग्रह?","पीत है जो अंबर","पीत और अंबर","पीत का अंबर","पीत से अंबर"],["\"अनुचित\" में उपसर्ग?","अन्","अनु","उचित","अ"],["\"एकता\" का विलोम?","अनेकता","एकत्व","एकल","भेद"],["\"परीक्षा\" का बहुवचन?","परीक्षाएँ","परीक्षों","परीक्षाओं","परीक्षी"],["\"अद्वितीय\" का अर्थ अनेक शब्दों में?","जिसके समान दूसरा न हो","जो दो हों","जो दूसरा हो","जो पहला हो"]],"pg":"46–52","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":48,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 46)","पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 49)","वाक्य क्रम, विज्ञापन; अभिव्यक्ति (పుట 50)","अभिव्यक्ति (शेष); भाषा की बात (పుట 51)","वाक्य रचना; परियोजना; समास (పుట 52)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 46)",["1. आवाज़ = ध्वनि, स्वर। 2. उदा.: कुत्ता सूँघकर मालिक को पहचान लेता है / मधुमक्खी नाचकर फूलों का पता बताती है / पक्षी खतरे पर विशेष आवाज़ करके दूसरों को सचेत करते हैं। 3. \"पशु-पक्षियों की भाषा\""]],["पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 49)",["प्रश्न: 1. विभिन्न भाषाएँ बोलने वाले भारतीयों को एकता के सूत्र में बाँधने का काम हिंदी ने किया; नेताओं ने हिंदी में भाषण देकर पूरे देश को स्वतंत्रता संग्राम से जोड़ा। 2. हिंदी सरल, शीघ्र सीखी जाने वाली, लिपि वैज्ञानिक (जैसा बोलते वैसा लिखते), अधिकांश लोगों द्वारा बोली-समझी जाने वाली भाषा है। 3. देशभर में संपर्क, रोज़गार (बैंक, मीडिया, फ़िल्म, अनुवाद), विदेशों में अवसर, साहित्य-संस्कृति का ज्ञान।","अ) 1. हिंदी आज विश्वभाषा है – नेपाल, मॉरिशस, फ़िजी, सूरीनाम, अमेरिका, इंग्लैंड आदि अनेक देशों में बोली-पढ़ाई जाती है, 150 से अधिक विश्वविद्यालयों में इसके कोर्स हैं और विश्व हिंदी दिवस मनाया जाता है। 2. भारत में अनेक भाषाएँ, धर्म, संस्कृतियाँ हैं, पर हिंदी सब प्रांतों के लोगों को जोड़ने वाली संपर्क भाषा है – इसलिए यह अनेकता में एकता का प्रतीक है।","आ) 1. हाँ 2. हाँ (14 सितंबर) 3. हाँ (10 जनवरी) 4. हाँ"]],["वाक्य क्रम, विज्ञापन; अभिव्यक्ति (పుట 50)",["इ) 1. हिंदी अपने शाब्दिक अर्थ से भी भारतीय कहलाती है। 2. 14 सितंबर को हिंदी दिवस मनाते हैं। 3. इस तरह हिंदी अंतर्राष्ट्रीय स्तर पर शोभित है। 4. अपने स्वास्थ्य का पूरा ध्यान रखना।","ई) 1. भारतीय स्टेट बैंक 2. राजभाषा अधिकारी (सहायक प्रबंधक) 3. ताकि योग्यता, आयु, शुल्क, परीक्षा आदि का पूरा विवरण जानकर सही आवेदन किया जा सके।","अभि. अ) 1. हिंदी में रामायण (तुलसी), सूर, कबीर, मीरा का भक्ति साहित्य है; हिंदी फ़िल्में, गीत, त्योहार पूरे देश की संस्कृति को जोड़ते हैं; हिंदी भारतीय संस्कृति की वाहक है। 2. भारत में अनेक भाषाएँ होने पर भी उत्तर से दक्षिण, पूरब से पश्चिम तक लोग आपस में हिंदी में बात करते हैं; यात्रा, व्यापार, नौकरी में हिंदी संपर्क भाषा है – इसलिए यह देश को जोड़ने वाली कड़ी है।"]],["अभिव्यक्ति (शेष); भाषा की बात (పుట 51)",["आ) स्वतंत्रता संग्राम में हिंदी ने पूरे देश को जोड़ा; आज भी यह सबसे अधिक बोली जाने वाली भाषा है; विभिन्न प्रांतों के लोग इसके माध्यम से एक-दूसरे को समझते हैं; राजभाषा के रूप में सरकारी कामकाज में भी इसका प्रयोग होता है – इसलिए राष्ट्रीय एकता की दृष्टि से हिंदी महत्वपूर्ण है।","इ) निबंध – \"हिंदी भाषा\": हिंदी भारत की राजभाषा है। इसकी लिपि देवनागरी है। 14 सितंबर 1949 को इसे राजभाषा का दर्जा मिला। यह सरल और वैज्ञानिक भाषा है। तुलसी, सूर, कबीर, प्रेमचंद, पंत, दिनकर जैसे महान साहित्यकारों ने इसे समृद्ध किया। आज यह विश्व के अनेक देशों में बोली जाती है। रोज़गार के लिए भी उपयोगी है। हमें हिंदी सीखकर इसका सम्मान करना चाहिए।","ई) हिंदी फ़िल्में, गीत, टीवी धारावाहिक, रेडियो, वेब सीरीज़ पूरे भारत और विदेशों में लोकप्रिय हैं; बॉलीवुड विश्व का बड़ा फ़िल्म उद्योग है; इससे हिंदी का प्रचार और रोज़गार दोनों बढ़े हैं।","भाषा की बात (अ) 1. आशा = उम्मीद – मुझे सफलता की उम्मीद है; समाधान = हल – हर समस्या का हल है; संकल्प = प्रण, दृढ़ निश्चय – मैंने रोज़ पढ़ने का प्रण लिया। 2. एकता × अनेकता – अनेकता में एकता भारत की विशेषता है; स्वदेश × विदेश – वह विदेश गया; प्राचीन × नवीन/आधुनिक – यह नवीन भवन है। 3. परीक्षा – परीक्षाएँ (परीक्षाएँ मार्च में हैं); संस्था – संस्थाएँ (कई संस्थाएँ सेवा करती हैं); दिशा – दिशाएँ (चार दिशाएँ होती हैं)।","(आ) 1. स+कुशल, अनु+क्रम, अन्+उचित 2. वर्ष+इक, खुश+ई, भारत+ईय 3. देश को – कर्म कारक; एकता के – संबंध कारक; सूत्र में – अधिकरण कारक; बाँधने के लिए – संप्रदान कारक; भाषा की – संबंध कारक","(इ) 1. सलाह – स्त्रीलिंग; सरकार – स्त्रीलिंग; संविधान – पुल्लिंग; संस्कृति – स्त्रीलिंग; समाधान – पुल्लिंग 2. अंतर्राष्ट्रीय 3. जिसके समान दूसरा कोई न हो"]],["वाक्य रचना; परियोजना; समास (పుట 52)",["ई) तीनों मिश्र वाक्य हैं – 1. \"मुझे पूरा विश्वास है\" (प्रधान उपवाक्य) + \"कि तुम हिंदी से अपना भविष्य बनाओगे\" (आश्रित संज्ञा उपवाक्य) 2. \"जो जानकारी दी गयी है\" (आश्रित विशेषण उपवाक्य) + \"उसे समझिए\" (प्रधान) 3. \"तुमने पूछा\" (प्रधान) + \"कि हिंदी का क्या महत्व है\" (आश्रित)","परियोजना: उदा. \"बरसते बादल\" का चित्र – 1. आकाश में काले बादल छाए हैं। 2. बारिश हो रही है। 3. मोर नाच रहा है। 4. पेड़-पौधे हरे-भरे हैं। 5. बच्चे खुशी से भीग रहे हैं।"]]]},{"id":"hi7","no":7,"t":"भक्ति पद","m":[9],"ty":"कविता – पद (కీర్తనలు)","th":"भक्ति, गुरु महिमा","by":"रैदास, मीराबाई","sum":"రైదాస్ పదంలో: \"ప్రభూ! నువ్వు చందనం, నేను నీరు – నీ సువాసన నా అణువణువునా వ్యాపించింది; నువ్వు దట్టమైన మేఘం, నేను నెమలిని; చకోరం చంద్రుణ్ణి చూసినట్లు నిన్ను చూస్తాను; నువ్వు ముత్యం, నేను దారం; బంగారంతో వెలిగారం కలిసినట్లు నీతో కలుస్తాను; నువ్వు స్వామి, నేను దాసుణ్ణి\" – భగవంతునితో అభేద భక్తి, దాస్య భక్తి. మీరాబాయి పదంలో: \"నేను రామరత్నమనే ధనం పొందాను; సద్గురువు దయతో అమూల్యమైన వస్తువు ఇచ్చాడు; జన్మజన్మల సంపద దొరికింది, లోకంలోని మిగతావన్నీ పోగొట్టుకున్నాను; ఈ ధనం ఖర్చు చేసినా తరగదు, దొంగలు దోచుకోలేరు, రోజురోజుకూ పెరుగుతుంది; సత్యమనే నావకు సద్గురువే నావికుడు – భవసాగరం దాటాను; గిరిధర నాగరుని కీర్తిని ఆనందంతో పాడుతున్నాను\" – మాధుర్య భక్తి, గురు మహిమ.","pts":["రైదాస్ (రవిదాస్) – 1482–1527 (పుస్తకం ప్రకారం); జ్ఞానమార్గీ శాఖ ప్రముఖ కవి; పదాలు \"గురు గ్రంథ్ సాహిబ్\" లో సంకలితం.","మీరాబాయి – 1498–1573; కృష్ణోపాసక కవయిత్రి; మాధుర్య భావ భక్తి; రచన: \"మీరాబాయి పదావళి\".","విధ: పదం (చౌపాయి) – లయ, తాళంతో పాడేవి; చౌపాయి మాత్రిక సమ ఛందం – నాలుగు చరణాలు, ప్రతి చరణంలో 16 మాత్రలు.","రైదాస్ భక్తి: దాస్య భావం, అభేదం (చందనం–నీరు, మేఘం–నెమలి, చంద్రుడు–చకోరం, ముత్యం–దారం, బంగారం–వెలిగారం, స్వామి–దాసుడు).","మీరా: \"పాయో జీ మ్హేఁ తో రామ రతన ధన పాయో\" – రామనామమే అమూల్య ధనం; సద్గురువే నావికుడు.","కబీర్ దోహా: \"गुरु गोविंद दोऊ खड़े, काके लागौं पाय। बलिहारी गुरु आपने, गोविंद दियो बताय॥\""],"w":[["बास","సువాసన"],["समानी","వ్యాపించింది"],["घन-बन","దట్టమైన మేఘం"],["चितवहि","చూస్తుంది"],["चकोर","చకోర పక్షి"],["सोनहि","బంగారానికి"],["सुहागा","వెలిగారం (బోరాక్స్)"],["अमोलक","అమూల్యమైన"],["सतगुरु","సద్గురువు"],["खूटै","తరిగిపోదు"],["सवायो","పావు వంతు ఎక్కువ"],["नाँव","నావ"],["खेवटिया","నావికుడు"],["भवसागर","సంసార సాగరం"],["हरख","ఆనందం (హర్ష)"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["छंद: कविता में वर्ण, मात्रा, यति आदि का संगठन. चौपाई – मात्रिक सम छंद, चार चरण, प्रत्येक चरण में 16 मात्राएँ.","मात्रा गणना: लघु (।) = 1 मात्रा (अ, इ, उ), गुरु (S) = 2 मात्राएँ (आ, ई, ऊ, ए, ऐ, ओ, औ, अनुस्वार, संयुक्ताक्षर से पहले वर्ण).","तत्सम रूप: बन – वन, रतन – रत्न, किरपा – कृपा.","वचन: मोती सागर में मिलते हैं; धागों से मालाएँ बनती हैं; मोर सुंदर पक्षी हैं."]},"qa":[["रैदास ने प्रभु को चंदन और अपने को क्या माना?","पानी।"],["रैदास ने अपने आप को मोर क्यों माना?","जैसे मोर बादल को देखकर नाचता है, वैसे ही भक्त प्रभु को देखकर आनंदित होता है।"],["मीरा ने कौन-सा धन पाया?","राम रतन धन (राम नाम)।"],["यह धन कैसा है?","खर्च करने से नहीं घटता, चोर नहीं लूट सकते, दिन-दिन सवाया बढ़ता है।"],["भवसागर पार करने में खेवटिया कौन है?","सतगुरु।"],["मीरा के प्रभु कौन हैं?","गिरिधर नागर (श्रीकृष्ण)।"]],"act":"\"भगवान की उपासना सच्चे हृदय से की जाती है, न कि ठाट-बाट से\" – इस भाव को दर्शाने वाली किसी कविता (कबीर, सूर, तुलसी, त्यागराज, अन्नमय्या) का संग्रह कर कक्षा में प्रस्तुत कीजिए।","kn":"\"अपना सामर्थ्य ही सबसे श्रेष्ठ बल है।\" – मनुस्मृति. \"उपकार करना मित्र का लक्षण है और अपकार करना शत्रु का।\"","qz":[["\"प्रभुजी, तुम चंदन हम पानी\" के कवि?","रैदास","मीराबाई","सूरदास","कबीर"],["रैदास के पद किस ग्रंथ में संकलित हैं?","गुरु ग्रंथ साहिब","रामचरितमानस","सूरसागर","पदावली"],["रैदास किस शाखा के कवि हैं?","ज्ञानमार्गी","प्रेममार्गी","कृष्णभक्ति","रामभक्ति"],["रैदास ने प्रभु को मोती माना तो अपने को?","धागा","सुहागा","पानी","चकोर"],["चकोर किसे देखता है?","चंद्र","सूर्य","बादल","मोर"],["मीराबाई किसकी उपासक थीं?","श्रीकृष्ण","राम","शिव","विष्णु"],["मीरा ने कौन-सा धन पाया?","राम रतन धन","सोना","मोती","चाँदी"],["मीरा को अमोलक वस्तु किसने दी?","सतगुरु ने","राजा ने","माँ ने","कृष्ण ने"],["सत की नाव का खेवटिया कौन?","सतगुरु","मीरा","कृष्ण","रैदास"],["\"खरच न खूटै, चोर न लूटै\" – किसके बारे में?","राम रतन धन","सोना","मोती","चंदन"],["मीरा की भक्ति किस भाव की है?","माधुर्य भाव","दास्य भाव","सख्य भाव","वात्सल्य भाव"],["चौपाई के प्रत्येक चरण में कितनी मात्राएँ?","16","13","24","11"],["\"किरपा\" का तत्सम रूप?","कृपा","क्रिपा","कृपया","किर्पा"],["\"सवायो\" का अर्थ?","सवा गुना बढ़ना","कम होना","खो जाना","बिकना"]],"wb":{"mis":"चौपाई में 16 मात्राएँ, दोहा में 13–11। लघु = 1, गुरु = 2 मात्राएँ। \"बन\" का तत्सम \"वन\", \"रतन\" का \"रत्न\"।","qz":[["\"बन\" का तत्सम?","वन","बान","बना","वान"],["\"रतन\" का तत्सम?","रत्न","रतना","रातन","रत्नम"],["\"नाँव\" का अर्थ?","नाव","नाम","नौ","गाँव"],["\"मोती सागर में मिलता है\" – बहुवचन?","मोती सागर में मिलते हैं","मोतियाँ सागर में मिलती हैं","मोतियों सागर में मिलता है","मोती सागरों में मिलता"],["\"स्वामी\" का विलोम?","सेवक (दास)","मालिक","राजा","गुरु"],["\"दिन\" का विलोम?","रात","सुबह","शाम","दोपहर"]],"pg":"59–63","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":61,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 59)","पाठ के पास के प्रश्न (పుట 60)","अर्थग्राह्यता-प्रतिक्रिया (పుట 61)","पद्यांश (शेष); अभिव्यक्ति; भाषा की बात (పుట 62)","तत्सम, अर्थ, वचन, छंद; परियोजना (పుట 63)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 59)",["1. गुरु। 2. गुरु को गोविंद (भगवान) से श्रेष्ठ बताया गया है, क्योंकि गुरु ने ही भगवान का ज्ञान दिया (गोविंद दियो बताय)। 3. आडंबर-रहित (दिखावा-रहित) सच्ची भक्ति से ही भगवान प्रसन्न होते हैं; इससे मन शुद्ध और शांत होता है।"]],["पाठ के पास के प्रश्न (పుట 60)",["1. दास्य और अनन्य भक्ति – प्रभु स्वामी, भक्त दास; प्रभु चंदन, भक्त पानी (प्रभु में घुल-मिल गया)। 2. जैसे मोर घने बादल को देखकर आनंद से नाचता है, वैसे ही रैदास प्रभु को देखकर आनंदित होते हैं। 3. जो सत्य का आचरण करे, ईश्वर भक्ति में लीन रहे, सबका भला करे, उसे संत कहते हैं। 4. मीरा की भक्ति माधुर्य भाव की, अनन्य और समर्पित है – उन्होंने कृष्ण को ही पति माना, सब कुछ त्याग दिया।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 61)",["अ) 1. रैदास की भक्ति दास्य भाव और ज्ञानमार्गी (निर्गुण) है – वे प्रभु को स्वामी और स्वयं को दास मानते हैं; मीरा की भक्ति माधुर्य भाव और सगुण (कृष्ण) है – वे कृष्ण को प्रियतम मानती हैं और गुरु कृपा से राम-नाम धन पाती हैं। 2. भक्ति से मन को शांति, धैर्य, सदाचार, प्रेम और दया मिलती है; अहंकार दूर होता है; कठिनाइयों में आत्मबल मिलता है।","आ) 1. प्रभुजी, तुम चंदन हम पानी। 2. मीरा के प्रभु गिरिधर नागर, हरख-हरख जस गायो।","इ) 1. सत्य की नाव है और उसे खेने वाले (नाविक) सतगुरु हैं; उनकी सहायता से मीरा संसार-सागर पार कर गईं। 2. प्रभु चंदन हैं और भक्त पानी; जैसे चंदन घिसने पर पानी के कण-कण में उसकी सुगंध फैल जाती है, वैसे ही प्रभु की भक्ति भक्त के अंग-अंग में समा गई है।","ई) 1. (अ) यशोदा 2. (अ) मधुबन"]],["पद्यांश (शेष); अभिव्यक्ति; भाषा की बात (పుట 62)",["ई) 3. (इ) शाम 4. (अ) छोटी 5. (इ) शत्रु","अ) 1. मैं ईश्वर की तुलना सूरज से करना चाहूँगा, क्योंकि सूरज बिना भेदभाव सबको प्रकाश और जीवन देता है; या माँ से, क्योंकि माँ की तरह ईश्वर निःस्वार्थ प्रेम करता है। 2. मीरा की भक्ति अनन्य, निःस्वार्थ, माधुर्य भाव की है; उन्होंने राजमहल, लोक-लाज सब छोड़कर कृष्ण को अपना सर्वस्व माना; गुरु की कृपा से राम-नाम धन पाकर आनंद से प्रभु का यश गाती हैं।","आ) मीरा कहती हैं – मुझे राम नाम रूपी रत्न-धन मिल गया है; सतगुरु ने कृपा करके यह अमूल्य वस्तु दी; जन्म-जन्म की पूँजी मिली, संसार का मोह छूट गया; यह धन खर्च करने से घटता नहीं, चोर लूट नहीं सकते, दिन-दिन बढ़ता है; सत्य की नाव पर सतगुरु नाविक बनकर मुझे भवसागर पार ले गए; मैं प्रसन्न होकर गिरिधर नागर का यश गाती हूँ।","इ) कविता: \"हे प्रभु तुम दीपक हम बाती, / तुम बिन सूनी जीवन-राती। / तुम सागर हम नदिया धारा, / तुम में मिलकर पाएँ किनारा।\"","ई) भक्ति साहित्य प्रेम, दया, समता, सत्य, त्याग, विनम्रता, गुरु-भक्ति सिखाता है; जाति-धर्म के भेद मिटाता है (रैदास, कबीर); मन को शुद्ध करता है – इसलिए मानवीय मूल्यों के विकास में इसकी बड़ी भूमिका है।","भाषा की बात (अ) 1. मोर = मयूर – मयूर राष्ट्रीय पक्षी है; पानी = जल, नीर – जल ही जीवन है; चंद्र = चाँद, शशि – शशि रात को चमकता है। 2. स्वामी × सेवक – सेवक ईमानदार है; गुरु × शिष्य – शिष्य गुरु का आदर करे; दिन × रात – रात में तारे चमकते हैं। 3. वर्तनी: (पाठ के अनुसार) सतगुरु, सभी, भक्ति।"]],["तत्सम, अर्थ, वचन, छंद; परियोजना (పుట 63)",["(आ) 1. बन – वन; रतन – रत्न; किरपा – कृपा 2. जग = संसार; नाँव = नाव; अमोलक = अमूल्य","(इ) 1. मोती सागर में मिलते हैं। 2. धागों से मालाएँ बनती हैं। 3. मोर सुंदर पक्षी हैं।","(ई) चौपाई: \"प्रभुजी, तुम चंदन हम पानी\" – प्रत्येक चरण में 16 मात्राएँ; चार चरण – मात्रिक सम छंद।","परियोजना: उदा. कबीर – \"मोको कहाँ ढूँढ़े बंदे, मैं तो तेरे पास में\"; तुलसी – \"तुलसी इस संसार में, भाँति-भाँति के लोग\" – संग्रह करके कक्षा में प्रस्तुत।"]]]},{"id":"hi8","no":8,"t":"स्वराज्य की नींव","m":[9],"ty":"एकांकी (ఏకాంకిక)","th":"देशभक्ति, त्याग","by":"विष्णु प्रभाकर","sum":"1857 స్వాతంత్ర్య సంగ్రామంలో గ్వాలియర్ దగ్గర యుద్ధభూమి దృశ్యం. రాణి లక్ష్మీబాయి సఖి జూహీతో \"స్వరాజ్యం దగ్గరికి వచ్చినట్లే వచ్చి దూరమవుతోంది; రాజులు, సర్దార్లు భోగవిలాసాల్లో మునిగారు; నేను ఒంటరిదాన్నైనా ఝాన్సీని వదలను\" అంటుంది. బాబా గంగాదాస్ మాట గుర్తుచేస్తుంది – \"ఎక్కువ-తక్కువ భేదాలు పోయి, విలాసప్రియులు జనసేవకులుగా మారే వరకు స్వరాజ్యం రాదు; అది బలిదానంతోనే వస్తుంది.\" జూహీ: \"స్వరాజ్యం పొందడం కంటే దాని స్థాపనకు నేల సిద్ధం చేసి పునాది రాయి కావడం గొప్ప.\" మందర్ తాత్యాను ఆటపాటల్లో మునిగాడని ఎగతాళి చేస్తే, తాత్యాను స్వామిగా భావించే జూహీ \"దేశం కోసం సర్దార్‌నైనా తిరస్కరిస్తాను\" అంటుంది. జనరల్ రోజ్ సేన మురార్‌లో పేష్వా సేనను ఓడించిన వార్త రఘునాథరావు తెస్తాడు. తాత్యా వస్తే రాణి వ్యంగ్యంగా మందలించి \"తలవార్ పట్టుకో, రాగరంగాలు మరచిపో; ఈ యుద్ధంలో గెలవకపోతే సేనను, సామగ్రిని శత్రువుకు దక్కకుండా తీసుకెళ్ళు\" అని ఆజ్ఞాపిస్తుంది. \"ఇది నా జీవితంలో చివరి యుద్ధం కావచ్చు; స్వరాజ్యం పొందుతాం లేదా దాని పునాది రాళ్ళమవుతాం\" అని రాణి యుద్ధానికి బయలుదేరుతుంది.","pts":["రచయిత: विष्णु प्रभाकर (1912–2009) – ఆదర్శప్రియ, \"ఆదర్శోన్ముఖ యథార్థవాది\" రచయిత; \"आवारा मसीहा\" కు సోవియట్ ల్యాండ్ నెహ్రూ పురస్కారం; పద్మభూషణ్.","విధ: एकांकी – ఒకే అంకం గల నాటకం; ఒక సంఘటన ప్రధానం; ఇది చారిత్రక సంఘటన ప్రధాన ఏకాంకిక.","పాత్రలు: लक्ष्मीबाई, जूही (సఖి/కర్నల్), मुंदर, रघुनाथराव, तात्या टोपे (సేనాపతి).","బాబా గంగాదాస్: \"బలిదానంతోనే స్వరాజ్యం\".","జనరల్ రోజ్ (బ్రిటిష్) – మురార్‌లో పేష్వా సేనను ఓడించాడు; గ్వాలియర్ కోట.","\"खूब लड़ी मर्दानी वह तो झाँसी वाली रानी थी\" – సుభద్రా కుమారి చౌహాన్."],"w":[["नींव","పునాది"],["स्वराज्य","స్వపరిపాలన"],["मंज़िल","గమ్యం"],["क्षितिज","దిగ్మండలం"],["प्रलय","వినాశనం"],["मशगूल","నిమగ్నమైన"],["विलासप्रिय","భోగాలను ఇష్టపడేవాడు"],["बलिदान","త్యాగం"],["दुत्कारना","తిరస్కరించు"],["मदहोशी","మత్తు"],["स्वामिभक्त","యజమానికి విశ్వాసపాత్రుడు"],["व्यंग्य","ఎత్తిపొడుపు"],["फटकारना","మందలించు"],["कलंकित","మచ్చపడిన"],["जागीर","భూమి కానుక"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["भाववाच्य/कर्मवाच्य: \"राजू पुस्तक पढ़ता है\" → \"राजू से पुस्तक पढ़ी जाती है\"; \"रानी ने आज्ञा दी\" → \"रानी द्वारा आज्ञा दी गयी\".","उपसर्ग: अ+सफलता, नि(र्)+आशा. प्रत्यय: वीर+ता, इतिहास+इक.","विलोम: असफलता × सफलता, विश्वास × अविश्वास.","वचन: शंका – शंकाएँ, किला – किले, सूचना – सूचनाएँ."]},"qa":[["लक्ष्मीबाई ने क्या प्रतिज्ञा की थी?","मैं अपनी झाँसी नहीं दूँगी।"],["बाबा गंगादास ने क्या कहा था?","जब तक ऊँच-नीच का भेद नहीं मिटता और विलासप्रिय लोग जनसेवक नहीं बनते, स्वराज्य नहीं मिलेगा; वह बलिदान से मिलेगा।"],["तात्या कौन थे?","पेशवा के सेनापति (तात्या टोपे)।"],["जनरल रोज की सेना ने कहाँ पेशवा की सेना को हराया?","मुरार में।"],["लक्ष्मीबाई तात्या से क्यों नाराज़ थीं?","वे युद्ध के समय राग-रंग, ब्रह्मभोज, जागीर बाँटने में डूबे थे।"],["लक्ष्मीबाई की अंतिम चिंता क्या थी?","स्वराज्य का झंडा कलंकित न होने पाए।"]],"act":"देशभक्ति से संबंधित किसी एकांकी का संकलन कर कक्षा में अभिनय कीजिए।","kn":"भारतीय संविधान: अनुच्छेद 14 (समानता), 15(1) (भेदभाव निषेध), 16 (अवसर की समानता), 39(घ) (समान कार्य के लिए समान वेतन), 15(3) (महिलाओं-बच्चों के लिए विशेष प्रावधान), 51(क)(ङ) (महिलाओं की गरिमा).","qz":[["\"स्वराज्य की नींव\" के लेखक?","विष्णु प्रभाकर","प्रेमचंद","दिनकर","काका कालेलकर"],["यह पाठ किस विधा का है?","एकांकी","कहानी","निबंध","पत्र"],["\"एकांकी\" का अर्थ?","एक अंक वाला","एक पात्र वाला","एक पृष्ठ वाला","एक गीत वाला"],["विष्णु प्रभाकर को सोवियत लैंड नेहरु पुरस्कार किस रचना पर मिला?","आवारा मसीहा","गोदान","कुरुक्षेत्र","चिदंबरा"],["लक्ष्मीबाई की सखी?","जूही","मीरा","अमीना","मरियम"],["लक्ष्मीबाई ने किसे \"कर्नल\" कहा?","जूही","मुंदर","रघुनाथ","तात्या"],["लक्ष्मीबाई की प्रतिज्ञा?","मैं अपनी झाँसी नहीं दूँगी","मैं ग्वालियर लूँगी","मैं युद्ध नहीं करूँगी","मैं संधि करूँगी"],["बाबा गंगादास के अनुसार स्वराज्य कैसे मिलेगा?","बलिदान से","धन से","संधि से","भोग से"],["पेशवा की सेना कहाँ हारी?","मुरार","झाँसी","कालपी","ग्वालियर"],["यह सूचना कौन लाया?","रघुनाथराव","तात्या","मुंदर","जूही"],["जनरल रोज किस पक्ष का था?","अंग्रेज़","पेशवा","मराठा","मुग़ल"],["\"नींव का पत्थर बनना\" का भाव?","आधार बनकर त्याग करना","पत्थर तोड़ना","घर बनाना","राजा बनना"],["\"असफलता\" में उपसर्ग?","अ","अस","सफल","ता"],["\"वीरता\" में प्रत्यय?","ता","वीर","रता","आ"]],"wb":{"mis":"कर्मवाच्य में कर्ता के साथ \"से/द्वारा\" और क्रिया \"जाना\" के रूप से (पढ़ी जाती है, दी गयी)। \"ऐतिहासिक\" में प्रत्यय \"इक\" है।","qz":[["\"राजू पुस्तक पढ़ता है\" – कर्मवाच्य?","राजू से पुस्तक पढ़ी जाती है","पुस्तक राजू पढ़ता","राजू ने पुस्तक पढ़ी","पुस्तक पढ़ता है राजू"],["\"रानी ने आज्ञा दी\" – कर्मवाच्य?","रानी द्वारा आज्ञा दी गयी","रानी आज्ञा देती है","आज्ञा रानी ने ली","रानी से आज्ञा देती"],["\"विश्वास\" का विलोम?","अविश्वास","निश्वास","विश्वासी","आश्वास"],["\"किला\" का बहुवचन?","किले","किलाएँ","किलों","किलें"],["\"ऐतिहासिक\" में प्रत्यय?","इक","इतिहास","सिक","ऐति"],["\"निराशा\" में उपसर्ग?","निर्","नि","आशा","निरा"]],"pg":"64–70","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":66,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 64)","पाठ के पास के प्रश्न (పుట 66)","पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 69)","गद्यांश; अभिव्यक्ति; भाषा की बात (పుట 70)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 64)",["1. विपत्ति में धैर्य और समयस्फूर्ति (सूझबूझ) से काम लेना चाहिए। 2. आदर्श शासक सबका बराबर ध्यान रखे, न्यायप्रिय, क्षमाशील, ईमानदार, प्रजा-हितैषी, कानून का पालन करने वाला और साहसी हो। 3. न्याय, समानता, सुरक्षा, कानून का पालन, प्रजा की भलाई, भ्रष्टाचार-मुक्त प्रशासन।"]],["पाठ के पास के प्रश्न (పుట 66)",["1. लक्ष्मीबाई अपनी सखी जूही से बातें कर रही हैं। 2. उन्हें इस बात का दुख है कि स्वराज्य पास आकर भी दूर चला जाता है और राजा-सरदार विलासिता में डूबे हैं।"]],["पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 69)",["3. तात्या युद्ध के समय राग-रंग, ब्रह्मभोज, उत्सव और जागीर बाँटने में लगे थे, देश की चिंता नहीं कर रहे थे। 4. यह मेरे जीवन का अंतिम युद्ध हो सकता है; मुझे जीत-हार की चिंता नहीं, चिंता केवल इस बात की है कि स्वराज्य का झंडा कलंकित न हो।","अ) 1. स्वराज्य के मार्ग में बहुत बड़ी कठिनाइयाँ (हिमालय जैसी बाधाएँ, शत्रु और अपनों का अविश्वास) आ रही हैं। 2. उस समय राजा-सरदार भोग-विलास में डूबे थे, आपस में अविश्वास था, ऊँच-नीच का भेद था, अंग्रेज़ों की सेना शक्तिशाली थी – इसलिए स्वराज्य कठिन था।","आ) 1. पेशवा के सेनापति (तात्या टोपे)। 2. जब तक ऊँच-नीच का भेद नहीं मिटता और विलासप्रिय लोग जनसेवक नहीं बनते, स्वराज्य नहीं मिलेगा; वह बलिदान से मिलेगा। 3. \"मैं अपनी झाँसी नहीं दूँगी।\" 4. क्योंकि वह तात्या को अपना स्वामी मानती है और जानती है कि वे स्वामिभक्त हैं; पर देश के लिए वह उन्हें भी ठुकरा सकती है।","इ) 1. स्वराज्य पाना ही सब कुछ नहीं, उसके लिए त्याग करके आधार तैयार करना (नींव का पत्थर बनना) और भी बड़ा कार्य है – भले ही हम उसका फल न देख पाएँ। 2. आपसी शंका से अविश्वास बढ़ेगा और निराशा मिटाने के लिए लोग और भी भोग-विलास (नाच-गाना) में डूबेंगे।"]],["गद्यांश; अभिव्यक्ति; भाषा की बात (పుట 70)",["ई) 1. भारतीय संविधान द्वारा महिलाओं को दिए गए अधिकारों के बारे में। 2. अनुच्छेद 15(1) – राज्य द्वारा (लिंग के आधार पर) कोई भेदभाव नहीं किया जाएगा। 3. अनुच्छेद 39(घ)।","अभि. 1. स्वराज्य की नींव = स्वतंत्रता के लिए आधार तैयार करने वाला त्याग, बलिदान, एकता, देशभक्ति और भेदभाव-रहित समाज; लक्ष्मीबाई, जूही, मुंदर जैसे वीर इसकी नींव के पत्थर बने। 2. \"हम सब मिलकर या तो स्वराज्य प्राप्त करेंगे या उसकी नींव का पत्थर बनेंगे\" – यह कथन अच्छा लगा, क्योंकि इसमें निःस्वार्थ देशभक्ति और बलिदान की भावना है।","आ) वीरांगना लक्ष्मीबाई ने झाँसी न देने की प्रतिज्ञा निभाई; पुरुष वेश में तलवार लेकर अंग्रेज़ों से लड़ीं; विलासी सरदारों को फटकारकर देशभक्ति जगाई; स्त्रियों (जूही, मुंदर) को सेना में आगे बढ़ाया; प्राण देकर भी स्वराज्य की नींव रखी – वे देशभक्ति की अद्भुत मिसाल हैं।","इ) कहानी: 1857 में ग्वालियर के पास युद्धभूमि में रानी लक्ष्मीबाई अपनी सखी जूही से कहती हैं कि राजा-सरदार विलासिता में डूबे हैं, फिर भी वे झाँसी नहीं देंगी। जूही याद दिलाती है कि स्वराज्य की नींव का पत्थर बनना भी महान है। मुंदर आती है। रघुनाथराव खबर लाते हैं कि जनरल रोज ने मुरार में पेशवा की सेना हरा दी। तात्या आते हैं, रानी उन्हें फटकारती हैं और युद्ध की आज्ञा देती हैं। सब मिलकर प्रण करते हैं – स्वराज्य लेंगे या उसकी नींव बनेंगे।","ई) साहस से कठिनाइयों का सामना होता है, वीरता से अन्याय का विरोध, आत्मविश्वास से सफलता और आत्मनिर्भरता से सम्मान मिलता है – लक्ष्मीबाई इन सबका उदाहरण हैं।","भाषा की बात 1. नारी = स्त्री, महिला – महिलाएँ हर क्षेत्र में आगे हैं; मित्र = दोस्त, सखा – सच्चा दोस्त संकट में साथ देता है; प्रेम = प्यार, स्नेह – माँ का स्नेह अनमोल है। 2. असफलता × सफलता – मेहनत से सफलता मिलती है; विश्वास × अविश्वास – अविश्वास से रिश्ते टूटते हैं। 3. शंका – शंकाएँ (मन की शंकाएँ दूर करो); किला – किले (राजस्थान में कई किले हैं); सूचना – सूचनाएँ (सूचनाएँ ध्यान से पढ़ो)।","उपसर्ग: अ+सफलता, निर्+आशा; प्रत्यय: वीर+ता, इतिहास+इक","वाच्य: 1. (बच्चे/वह) से भोजन किया जाता है। 2. रानी द्वारा आज्ञा दी गयी। 3. लक्ष्मीबाई द्वारा (युद्ध किया गया / प्रतिज्ञा की गयी)।","शब्द परिवर्तन: कक्षा में एक लड़का (छात्र / बालक) आया; एक लड़की (छात्रा / बालिका) आयी। सब लड़के (छात्र / बालक) कक्षा में पहुँच चुके हैं।","परियोजना: देशभक्ति से संबंधित एकांकी (उदा. \"भारत माता\", \"सिपाही की माँ\") का संकलन और अभिनय।"]]]},{"id":"hi9","no":9,"t":"दक्षिणी गंगा गोदावरी","m":[10],"ty":"यात्रा-वृत्तांत (యాత్రా వృత్తాంతం)","th":"नदी का सौंदर्य, संस्कृति","by":"काका कालेलकर","sum":"చెన్నై నుండి రాజమహేంద్రికి రైలులో వెళ్తూ బెజవాడ దాటాక సూర్యోదయం; వర్షాకాలం కాబట్టి ఎటు చూసినా పచ్చదనం; రైలు పట్టాల పక్కన కాలువ, సీతాకోకచిలుకల్లా పాలెత్తిన పడవలు, కొంగలు. కొవ్వూరు స్టేషన్ దాటాక గోదావరి తల్లి దర్శనం. వంతెనపై నుండి అత్యంత విశాలమైన గోదావరి ప్రవాహం – లేఖకుడు ఎన్నో మహానదులను చూసినా రాజమహేంద్రి దగ్గర గోదావరి వైభవం విశిష్టం; పశ్చిమాన కొండలు, సాంవళ మేఘాల నీడలో నీలమైన జలం, కొండలపై దిగిన మేఘాలు ధ్యానంలో ఉన్న ఋషుల్లా ఉన్నాయి. విపత్తుల నుండి విజయంతో బయటపడిన దేశంలా గోదావరి గంభీరంగా ప్రవహిస్తుంది; పడవలు, ఓడలు దాని పిల్లలు. ప్రవాహం మధ్యలో టాపులు (లంకలు) – కొన్ని పురాతన ధర్మాల్లా స్థిరం, కొన్ని కవి ప్రతిభలా క్షణక్షణం మారుతాయి; బగుళ్ళు (కొంగలు) వాటిపై పాదముద్రలు వేస్తాయి. నదీతీరం మనిషి కృతజ్ఞతకు నిత్యోత్సవం – దేవాలయాలు, ఘాట్లు; భక్తులు గంగాజలం సగం గోదావరిలో పోసి గోదావరి జలం నింపుకుంటారు. ధవళేశ్వరం, రాజమహేంద్రి ప్రజలు ఆనందంగా ఉన్నారు. \"గోదావరి తల్లీ! రామ-లక్ష్మణ-సీతల నుండి వృద్ధ జటాయువు వరకు నీ తీరంలో వీరులు, పండితులు, రాజనీతిజ్ఞులు, భక్తులు పుట్టారు; నీ జలం ఒక్క చుక్క కూడా వ్యర్థం కాదు\" అని లేఖకుడు నమస్కరిస్తాడు.","pts":["లేఖకుడు: काका कालेलकर – అసలు పేరు దత్తాత్రేయ బాలకృష్ణ కాలేల్కర్ (1885–1981); గాంధేయవాది.","హిందుస్తానీ ప్రచార సభ ద్వారా హిందీ సేవ; రాజ్యసభ సభ్యుడు; పద్మవిభూషణ్, సాహిత్య అకాడమీ పురస్కారాలు.","పాఠం \"सप्त सरिता\" రచన నుండి.","విధ: यात्रा-वृत्तांत – గద్య విధ; లేఖకుడు దర్శనీయ స్థల యాత్రానుభూతులను వర్ణిస్తాడు.","గోదావరి = దక్షిణ గంగ; \"ధీర-గంభీర మాత\"; రాజమహేంద్రి (రాజమండ్రి), ధవళేశ్వరం, కొవ్వూరు.","ఆంధ్రను \"అన్నపూర్ణ\", \"భారత ధాన్యాగారం\" అంటారు – కృష్ణా, గోదావరి డెల్టాల వల్ల."],"w":[["वृत्तांत","వర్ణన, వివరణ"],["नहर","కాలువ"],["पाल","తెరచాప"],["नौका","పడవ"],["अथाह","లోతైన"],["बगुला","కొంగ"],["पाट","నది వెడల్పు"],["भव्य","గొప్ప"],["टापू","లంక, ద్వీపం"],["अनासक्त","ఆసక్తి లేని"],["धवल","తెల్లని"],["कृतज्ञता","కృతజ్ఞత"],["सरित्पति","సముద్రం"],["संभ्रम","ఆత్రుత, తొందర"],["अधिष्ठात्री","అధిపతి దేవత"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["संधि: सूर्योदय = सूर्य + उदय (गुण); पवित्र = पो + इत्र (अयादि); अत्यंत = अति + अंत (यण्).","समास: साधु-संत – साधु और संत (द्वंद्व); चरणचिह्न – चरण का चिह्न (तत्पुरुष); गंगाजल – गंगा का जल (तत्पुरुष).","अकर्मक क्रिया (कर्म नहीं): सोना, हँसना, उठना, दौड़ना, चलना. सकर्मक क्रिया (कर्म सहित): पढ़ना, पीना, कहना, खाना.","विलोम: विजय × पराजय, प्रसिद्ध × अप्रसिद्ध/गुमनाम, दुर्लभ × सुलभ."]},"qa":[["लेखक कहाँ से कहाँ जा रहे थे?","चेन्नई से राजमहेंद्री।"],["सूर्योदय कहाँ हुआ?","बेजवाड़े से आगे।"],["गोदावरी के दर्शन कब होने लगे?","कोव्वूर स्टेशन पार करने के बाद।"],["पहाड़ों पर उतरे बादल कैसे लगते थे?","ध्यानस्थ ऋषि-मुनियों जैसे।"],["नदी का किनारा किसका उत्सव है?","मनुष्य की कृतज्ञता का अखंड उत्सव।"],["गोदावरी को क्या संज्ञा दी गयी है?","दक्षिणी गंगा, धीर-गंभीर माता।"]],"act":"यात्रा-वृत्तांत विधा की जानकारी प्राप्त कीजिए; अपनी किसी यात्रा (उदा. तिरुपति, श्रीशैलम, विशाखपट्टणम) का वृत्तांत लिखकर कक्षा में पढ़िए।","kn":"उपवाचक: \"अपने स्कूल को एक उपहार\" (ऋतु भूषण). पठन हेतु कविता: \"माँ मुझे आने दे!\" (मृदुल जोशी).","qz":[["\"दक्षिणी गंगा गोदावरी\" के लेखक?","काका कालेलकर","विष्णु प्रभाकर","प्रेमचंद","भगवतशरण उपाध्याय"],["काका कालेलकर का पूरा नाम?","दत्तात्रेय बालकृष्ण कालेलकर","धनपत राय","रामधारी सिंह","विनोबा भावे"],["यह पाठ किस विधा का है?","यात्रा-वृत्तांत","एकांकी","निबंध","पत्र"],["यह पाठ किस रचना से लिया गया?","सप्त सरिता","मानसरोवर","कुरुक्षेत्र","आवारा मसीहा"],["लेखक किस शहर जा रहे थे?","राजमहेंद्री","विजयवाड़ा","चेन्नई","विशाखपट्टणम"],["सूर्योदय कहाँ से आगे हुआ?","बेजवाड़ा","चेन्नई","कोव्वूर","धवलेश्वर"],["गोदावरी के दर्शन किस स्टेशन के बाद?","कोव्वूर","निडदवोलु","एलूरु","तणुकु"],["पहाड़ों पर उतरे बादल किनके जैसे लगे?","ध्यानस्थ ऋषि-मुनि","सैनिक","हाथी","बच्चे"],["नदी के बच्चे कौन हैं?","नाव और जहाज़","मछलियाँ","टापू","बगुले"],["टापुओं पर कौन चरणचिह्न छोड़ते हैं?","बगुले","मनुष्य","हाथी","मोर"],["गोदावरी को कैसी माता कहा गया है?","धीर-गंभीर","चंचल","क्रोधी","कोमल"],["\"सूर्योदय\" का संधि विच्छेद?","सूर्य + उदय","सूर्यो + दय","सूर + उदय","सूर्य + ओदय"],["\"दुर्लभ\" का विलोम?","सुलभ","अलभ्य","दुलभ","अभाव"],["अकर्मक क्रिया कौन-सी है?","सोना","पढ़ना","खाना","पीना"]],"wb":{"mis":"सकर्मक क्रिया में \"क्या?\" का उत्तर (कर्म) मिलता है – खाना (क्या खाया?), अकर्मक में नहीं – सोना, हँसना। \"पवित्र\" = पो + इत्र (अयादि संधि)।","qz":[["\"अत्यंत\" का संधि विच्छेद?","अति + अंत","अत्य + अंत","अ + त्यंत","अती + अंत"],["\"पवित्र\" का संधि विच्छेद?","पो + इत्र","प + वित्र","पवि + त्र","पौ + इत्र"],["\"गंगाजल\" में समास?","तत्पुरुष","द्वंद्व","द्विगु","बहुव्रीहि"],["\"साधु-संत\" में समास?","द्वंद्व","तत्पुरुष","कर्मधारय","अव्ययीभाव"],["सकर्मक क्रिया?","कहना","उठना","दौड़ना","हँसना"],["\"विजय\" का विलोम?","पराजय","जय","विजेता","अजय"]],"pg":"72–76","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":74,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 72)","पाठ के पास के प्रश्न (పుట 73)","पाठ के पास के प्रश्न (పుట 74)","अर्थग्राह्यता-प्रतिक्रिया (పుట 75)","गद्यांश (शेष); अभिव्यक्ति; भाषा की बात (పుట 76)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 72)",["1. नदियों, बूँदों और हवा (प्रकृति के सौंदर्य) के बारे में। 2. गोदावरी, कृष्णा, कावेरी, तुंगभद्रा, पेन्ना (पेन्नार), वंशधारा। 3. गोदावरी दक्षिण भारत की सबसे लंबी नदी है; महाराष्ट्र के नासिक (त्र्यंबकेश्वर) से निकलकर तेलंगाना, आंध्र प्रदेश से होती हुई बंगाल की खाड़ी में मिलती है; इसे दक्षिणी गंगा कहते हैं; राजमहेंद्री में पुष्कर मेला होता है।"]],["पाठ के पास के प्रश्न (పుట 73)",["1. बरसात के दिन थे; चारों ओर तरह-तरह की हरियाली फैली थी, नहर में पाल वाली नावें, रंग-बिरंगे बादलों की परछाईं, बगुले और ठंडी हवा – वातावरण बहुत सुहावना था। 2. क्योंकि वहाँ गोदावरी का पाट अत्यंत विशाल है, पहाड़, बादल, टापू, नावें मिलकर भव्य दृश्य बनाते हैं – ऐसा सौंदर्य लेखक ने कहीं और नहीं देखा।"]],["पाठ के पास के प्रश्न (పుట 74)",["3. (भँवर/तूफ़ान का स्वाँग) – प्रवाह में भँवर अचानक भयानक तूफ़ान का रूप दिखाकर गायब हो जाते हैं। 4. गोदावरी के तट पर मंदिर, महल, घाट, शिखर हैं; भक्त गंगाजल गोदावरी में डालकर गोदावरी जल भरते हैं; राम-सीता से लेकर वीर, विद्वान, भक्त यहाँ हुए।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 75)",["6. गोदावरी विशाल, शांत, गहरी और गंभीरता से बहती है; सबका पालन-पोषण करती है; समुद्र से मिलने जाते समय भी संयम रखती है – इसलिए धीर-गंभीर माता कहा।","अ) 1. लेखक को गोदावरी का जल पवित्र, अमोघ शक्ति वाला, अमृत समान और माता के स्नेह जैसा लगा होगा। 2. मैं कहता – \"गोदावरी विशाल चादर की तरह फैली है, उस पर नावें तैर रही हैं, किनारों पर हरे-भरे खेत और नारियल के पेड़ हैं, सूरज की किरणें जल पर सोने की तरह चमक रही हैं; यह नदी आंध्र की जीवनरेखा है।\"","आ) 1. हाँ 2. हाँ 3. हाँ 4. नहीं (वे आनंद मना रहे थे)","इ) 1. भूदान आंदोलन विनोबाजी के जीवन का प्रमुख कार्य था।"]],["गद्यांश (शेष); अभिव्यक्ति; भाषा की बात (పుట 76)",["इ) 2. \"जब तक देश परतंत्र है, तब तक देश गरीब है; जब तक देश की जनता दुखी है, आराम से रहना अपराध है।\" 3. (रेखांकित शब्द के अनुसार) उदा. आंदोलन – आंदोलनों (स्वतंत्रता के लिए अनेक आंदोलन हुए) 4. \"आचार्य विनोबा भावे\"","ई) मुख्य शब्द: भागमती गोदावरी, विशाल पाट, बेजवाड़ा, गर्व, शान-शौकत, निराली।","अ) 1. उदा. – \"मैं परिवार के साथ तिरुपति गया। अलिपिरि से सीढ़ियाँ चढ़ते समय पहाड़ों का हरा-भरा सौंदर्य, ठंडी हवा और भक्तों का उत्साह देखकर मन प्रसन्न हुआ। दर्शन के बाद हमने लड्डू प्रसाद लिया। यह यात्रा अविस्मरणीय रही।\" 2. कृष्णा, गोदावरी नदियों के डेल्टा, नहरों और उपजाऊ ज़मीन के कारण आंध्र में बहुत धान पैदा होता है; यहाँ का चावल देशभर में जाता है – इसलिए अन्नपूर्णा और भारत का धान्यागार कहलाता है।","आ) 1. लेखक ने हरियाली, नहर, पाल वाली नावें, बगुले देखकर आनंद पाया; गोदावरी का विशाल प्रवाह देखकर गर्व, श्रद्धा और विस्मय से भर गए; पहाड़, बादल, टापू देखकर उनका मन काव्यमय हो गया; अंत में वे गोदावरी माता को श्रद्धा से प्रणाम करते हैं। 2. गोदावरी माता की तरह सबका पालन-पोषण करती है, खेतों को सींचती है, अन्न देती है; उसके तट पर राम-सीता से लेकर वीर, भक्त, विद्वान पले – इसलिए लेखक ने उसे माता कहा।","इ) पत्र/वृत्तांत: अपनी यात्रा का वर्णन मित्र को पत्र के रूप में। ई) गोदावरी को माता कहकर श्रद्धा प्रकट करना, पहाड़ पर उतरे बादलों को ध्यानस्थ ऋषि कहना – यह अनुभव बहुत अच्छा लगा।","भाषा की बात 1. बरसात = वर्षा – वर्षा से धरती हरी होती है; सरिता = नदी – नदी कल-कल बहती है; पहाड़ = पर्वत, गिरि – हिमालय ऊँचा पर्वत है। 2. विजय × पराजय; प्रसिद्ध × अप्रसिद्ध; दुर्लभ × सुलभ 3. नहर – नहरें; तितली – तितलियाँ; कविता – कविताएँ; लहर – लहरें","संधि: सूर्योदय = सूर्य + उदय; पवित्र = पो + इत्र; अत्यंत = अति + अंत. समास: साधु-संत (द्वंद्व), चरणचिह्न (तत्पुरुष), गंगाजल (तत्पुरुष)","क्रिया: अकर्मक – सोना, हँसना, उठना, दौड़ना, चलना; सकर्मक – पढ़ना, पीना, कहना, खाना"]]]},{"id":"hi10","no":10,"t":"नीति दोहे","m":[10],"ty":"कविता – दोहे (ద్విపదలు)","th":"नैतिक मूल्य","by":"रहीम, बिहारी","sum":"రహీమ్ దోహాలు: (1) \"కహి రహీమ్ సంపతి సగే…\" – సంపద ఉన్నప్పుడు ఎన్నో విధాలుగా ఎందరో బంధువులు అవుతారు; కానీ ఆపద అనే గీటురాయిపై పరీక్షకు నిలిచినవారే నిజమైన మిత్రులు. (2) \"రహిమన్ పానీ రాఖియే…\" – నీటిని (గౌరవాన్ని/మెరుపును) కాపాడుకోవాలి; నీరు లేకపోతే అంతా శూన్యం; \"పానీ\" పోతే ముత్యానికి మెరుపు, మనిషికి గౌరవం, సున్నానికి (పిండికి) తడి పోయి విలువ ఉండదు. బిహారీ దోహాలు: (3) \"కనక-కనక తైఁ సౌ గునీ…\" – బంగారం (కనకం) యొక్క మత్తు ధతూరా (కనకం) కంటే వందరెట్లు ఎక్కువ; ధతూరా తింటే మనిషి పిచ్చివాడవుతాడు, బంగారం దొరికితేనే పిచ్చివాడవుతాడు (యమక అలంకారం). (4) \"నర కీ అరు నల-నీర కీ…\" – మనిషి గతి, నల్లా (పంపు) నీటి గతి ఒకటే; ఎంత కిందికి (వినయంగా) వంగుతాడో అంత పైకి ఎదుగుతాడు – వినయమే ఉన్నతికి మార్గం.","pts":["రహీమ్ (1556–1626) – పూర్తి పేరు అబ్దుర్ రహీమ్ ఖాన్-ఎ-ఖానా; అక్బర్ మిత్రుడు, ప్రధాన సేనాపతి, మంత్రి; సంస్కృతం, అరబీ, ఫారసీ పండితుడు.","రహీమ్ రచనలు: रहीम सतसई, बरवै नायिका भेद, श्रृंगार सोरठा.","బిహారీ (1595–1663) – రచన: बिहारी सतसई; దోహాలు నీతిపరంగా; \"గాగర్ మేఁ సాగర్\" (కుండలో సముద్రం) అని ప్రశంస.","దోహా: మాత్రిక ఛందం; 1, 3 చరణాల్లో 13 మాత్రలు, 2, 4 చరణాల్లో 11 మాత్రలు.","యమక అలంకారం: ఒకే పదం భిన్న అర్థాల్లో మళ్ళీ రావడం – \"కనక\" = బంగారం, ధతూరా.","\"పానీ\" మూడు అర్థాలు: మెరుపు (ముత్యం), గౌరవం (మనిషి), నీరు (సున్నం/పిండి)."],"w":[["संपति","సంపద"],["सगे","బంధువులు"],["बिपति","ఆపద"],["कसौटी","గీటురాయి"],["साँचे मीत","నిజమైన మిత్రులు"],["सून","శూన్యం"],["ऊबरै","ఉద్ధరించబడదు, నిలవదు"],["मानुष","మనిషి"],["चून","సున్నం / పిండి"],["कनक","బంగారం; ధతూరా"],["मादकता","మత్తు"],["बौराइ","పిచ్చివాడవు"],["नर","మనిషి"],["नल-नीर","నల్లా నీరు"],["नीचो","కిందికి (వినయం)"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["यमक अलंकार: एक ही शब्द की पुनरावृत्ति भिन्न-भिन्न अर्थों में – \"कनक-कनक तैं सौ गुनी\" (कनक = सोना, धतूरा).","दोहा छंद: मात्रिक छंद; पहले-तीसरे चरण में 13, दूसरे-चौथे में 11 मात्राएँ – \"रहिमन पानी राखिए (13), बिन पानी सब सून (11)\".","द्वंद्व समास: दोनों पद प्रधान, \"और/अथवा/या\" – रात-दिन, दाल-चावल, माता-पिता. अव्ययीभाव: प्रतिदिन, यथाशक्ति, रातोंरात, यथासंभव, भरपेट.","प्रत्यय \"इक\": धर्म–धार्मिक, नीति–नैतिक, पुराण–पौराणिक, समाज–सामाजिक."]},"qa":[["रहीम के अनुसार सच्चे मित्र की पहचान कब होती है?","विपत्ति (मुसीबत) के समय।"],["\"पानी\" शब्द के तीन अर्थ?","मोती के लिए चमक, मनुष्य के लिए इज़्ज़त (मान), चूने/आटे के लिए जल।"],["सोने की मादकता धतूरे से कितनी अधिक है?","सौ गुनी।"],["सोना पाने पर क्या होता है?","मनुष्य पागल (घमंडी) हो जाता है।"],["बिहारी ने नर और नल-नीर की गति कैसी बताई?","एक जैसी – जितना नीचा (विनम्र) होकर चलता है, उतना ऊँचा उठता है।"],["बिहारी के दोहों के लिए क्या कहा जाता है?","\"गागर में सागर\" भर देना।"]],"act":"इस पुस्तक के हर पृष्ठ पर दिए गए नीति वाक्यों में से अपनी मनपसंद दस नीतियों की सूची बनाकर कक्षा में प्रदर्शित कीजिए।","kn":"\"नीतिशास्त्र ही इस पृथ्वी का अमृत है।\" – महाभारत. \"परोपकार का प्रत्येक कार्य स्वर्ग की ओर एक कदम है।\"","qz":[["\"रहिमन पानी राखिए\" के कवि?","रहीम","बिहारी","कबीर","तुलसी"],["रहीम किसके मित्र और सेनापति थे?","अकबर","बाबर","शाहजहाँ","औरंगज़ेब"],["बिहारी की प्रसिद्ध रचना?","बिहारी सतसई","रहीम सतसई","सूरसागर","रामचरितमानस"],["\"गागर में सागर\" किसके दोहों के लिए कहा जाता है?","बिहारी","रहीम","कबीर","मीरा"],["सच्चे मित्र की कसौटी?","विपत्ति","संपत्ति","उत्सव","यात्रा"],["\"पानी गये न ऊबरै\" – इनमें कौन नहीं?","सोना","मोती","मानुष","चून"],["मोती के लिए \"पानी\" का अर्थ?","चमक","जल","इज़्ज़त","नमी"],["मनुष्य के लिए \"पानी\" का अर्थ?","इज़्ज़त (मान)","चमक","जल","पसीना"],["\"कनक\" के दो अर्थ?","सोना, धतूरा","सोना, चाँदी","पानी, दूध","फूल, फल"],["सोने की मादकता धतूरे से कितनी?","सौ गुनी","दस गुनी","दुगुनी","हज़ार गुनी"],["नर और नल-नीर – जितना नीचा चलें?","उतना ऊँचा होइ","उतना नीचा होइ","उतना छोटा होइ","उतना दूर होइ"],["\"कनक-कनक तैं सौ गुनी\" – अलंकार?","यमक","अनुप्रास","उपमा","रूपक"],["दोहे के पहले चरण में मात्राएँ?","13","11","16","24"],["\"माता-पिता\" में समास?","द्वंद्व","द्विगु","तत्पुरुष","अव्ययीभाव"]],"wb":{"mis":"यमक में एक ही शब्द अलग-अलग अर्थों में आता है (कनक-कनक); अनुप्रास में केवल वर्ण दोहराया जाता है। दोहा 13-11, चौपाई 16।","qz":[["बेमेल शब्द: नीर, पीर, जल, पानी","पीर","नीर","जल","पानी"],["\"नैतिक\" में प्रत्यय?","इक","नीति","तिक","नै"],["\"यथाशक्ति\" में समास?","अव्ययीभाव","द्वंद्व","तत्पुरुष","कर्मधारय"],["\"रात-दिन\" में समास?","द्वंद्व","द्विगु","अव्ययीभाव","बहुव्रीहि"],["दोहे के दूसरे चरण में मात्राएँ?","11","13","16","12"],["\"सामाजिक\" का मूल शब्द?","समाज","सामा","जिक","समाजी"]],"pg":"79–82","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":81,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 79)","दोहों के पास के प्रश्न; अर्थग्राह्यता (పుట 80)","अभ्यास; अभिव्यक्ति; भाषा की बात (పుట 81)","यमक, दोहा, प्रत्यय; परियोजना (పుట 82)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 79)",["1. बिना फल वाले वृक्ष व्यर्थ ही अपनी अकड़ दिखाते हैं (घमंडी होते हैं)। 2. फलदार वृक्ष फलों के भार से धरती तक झुक जाते हैं – विनम्र होते हैं और सबको फल देते हैं। 3. बुलबुल मीठा बोलती है, इसलिए सबका प्यार पाती है; कौवे की कर्कश बोली उसे अपमानित करवाती है।"]],["दोहों के पास के प्रश्न; अर्थग्राह्यता (పుట 80)",["1. विपत्ति (मुसीबत) के समय सच्चे मित्र की पहचान होती है। 2. \"पानी\" – मोती के लिए चमक, मनुष्य के लिए इज़्ज़त, चूने के लिए जल। 3. जैसे पानी (चमक) जाने पर मोती बेकार, इज़्ज़त जाने पर मनुष्य और पानी के बिना चूना बेकार हो जाता है – इसलिए मान-मर्यादा बनाए रखनी चाहिए। 4. सोना पाकर मनुष्य घमंड से पागल हो जाता है। 5. नर की गति नल के पानी जैसी बताई। 6. मनुष्य को विनम्र (नम्र) होकर चलना चाहिए।","अ) 1. नीति वचन हमें सही-गलत की पहचान, अच्छा आचरण, विनम्रता, सच्ची मित्रता, मान-मर्यादा सिखाते हैं; जीवन को सफल और सम्मानित बनाते हैं। 2. विनम्र मनुष्य को सब आदर देते हैं; विनम्रता से ज्ञान, मित्र और उन्नति मिलती है; घमंडी का पतन होता है – \"जेतो नीचो ह्वै चलै, तेतो ऊँचो होइ\"।"]],["अभ्यास; अभिव्यक्ति; भाषा की बात (పుట 81)",["आ) 1. ध्वनि साम्य: सगे–रीत/मीत, सून–चून, अधिकाइ–बौराइ, जोइ–होइ, कनक–कनक 2. तीन बार – मोती के लिए चमक, मनुष्य के लिए इज़्ज़त, चूने के लिए जल","इ) 1. रहीम कहते हैं कि पानी को (मान-मर्यादा को) बनाए रखो; बिना पानी के सब सूना है; पानी (चमक) जाने पर मोती, पानी (इज़्ज़त) जाने पर मनुष्य और पानी जाने पर चूना किसी काम का नहीं रहता। 2. सोने में धतूरे से सौ गुना अधिक नशा है; धतूरा खाने से मनुष्य पागल होता है, पर सोना तो पाने मात्र से ही मनुष्य पागल (घमंडी) हो जाता है।","अभि. अ) 1. रहीम ने कहा कि पानी (जल, चमक, इज़्ज़त) के बिना सब कुछ सूना है; मोती, मनुष्य और चूना – तीनों के लिए पानी ज़रूरी है; इसलिए हमें पानी बचाना और अपनी इज़्ज़त बनाए रखनी चाहिए। 2. धतूरा खाने से नशा चढ़ता है, पर धन (सोना) तो मिलते ही घमंड का नशा चढ़ा देता है; धन का नशा धतूरे से भी अधिक खतरनाक है – यह बताने के लिए तुलना की।","आ) दोहा 1 (रहीम): संपत्ति के समय बहुत लोग रिश्तेदार बन जाते हैं, पर विपत्ति में जो साथ दे वही सच्चा मित्र है। दोहा 4 (बिहारी): मनुष्य और नल के पानी की गति एक जैसी है – जितना नीचे झुककर (विनम्र होकर) चलते हैं, उतना ही ऊँचे उठते हैं।","इ) सूक्तियाँ: \"विपत्ति में साथ दे, वही सच्चा मित्र\"; \"इज़्ज़त गई तो सब गया\"; \"धन का घमंड सबसे बड़ा नशा\"; \"विनम्रता उन्नति की सीढ़ी\"। ई) \"नर की अरु नल-नीर की…\" – क्योंकि यह विनम्रता का सुंदर संदेश देता है।","भाषा की बात (अ) 1. पीर (पीड़ा; बाकी = पानी) 2. रीत (रीति; बाकी = मित्र) 3. मग (रास्ता; बाकी = संसार)"]],["यमक, दोहा, प्रत्यय; परियोजना (పుట 82)",["आ) यमक: \"कनक-कनक तैं सौ गुनी\" – पहले कनक का अर्थ सोना, दूसरे का धतूरा; एक ही शब्द भिन्न अर्थों में आया है।","इ) 1. यमक उदाहरण: \"काली घटा का घमंड घटा।\" (घटा = बादल; घटा = कम हुआ) 2. दोहा उदाहरण: \"बड़ा हुआ तो क्या हुआ, जैसे पेड़ खजूर। पंथी को छाया नहीं, फल लागे अति दूर॥\" (कबीर)","ई) 1. धार्मिक (धर्म+इक) – तिरुपति धार्मिक स्थल है। 2. नैतिक (नीति+इक) – नैतिक शिक्षा ज़रूरी है। 3. पौराणिक (पुराण+इक) – रामायण पौराणिक कथा है। 4. सामाजिक (समाज+इक) – दहेज एक सामाजिक बुराई है।","परियोजना: पुस्तक के पृष्ठों पर दिए नीति वाक्यों में से दस चुनकर चार्ट बनाना।"]]]},{"id":"hi11","no":11,"t":"जल ही जीवन है","m":[11],"ty":"कहानी – विज्ञान कथा (కథ)","th":"जल संरक्षण","by":"श्री प्रकाश","sum":"21వ శతాబ్దం ముగిసి 22వ శతాబ్దం ప్రారంభం కాబోతోంది; మనిషి ఎంతో ప్రగతి సాధించాడు. ఒక రోజు పత్రికలో – భూమిపై నీటి పరిమాణం అకస్మాత్తుగా తగ్గిపోయిందని సర్వే వార్త. భూవిజ్ఞాన శాస్త్రవేత్త ప్రొ. దీపేశ్ సాయంత్రం లాన్‌లో కూర్చొని ఆకాశంలో నాట్యం చేస్తూ భూమి దగ్గరికి వచ్చి వెనక్కి వెళ్ళే \"నక్షత్రం\" చూశాడు – అది అంతరిక్ష యానం! ఇతర గ్రహాలపై జీవం కోసం పరిశోధిస్తున్న ప్రొ. వికాస్‌కు చెప్పాడు. మరుసటి సాయంత్రం యానం తోటలో దిగింది; మనిషి లాంటి కానీ పెద్ద ఆకారం బయటికి వచ్చి \"మేము ఒక కాంతి సంవత్సరం దూరంలోని గ్రహం నుండి ఒక మిషన్‌పై వచ్చాం\" అంది. వారి గ్రహంలో ఒక రకమైన వైరస్ కలిసి నీరు విషమైంది, మహమ్మారి వ్యాపించింది; నీరు శుద్ధి అయ్యే వరకు భూమి నుండి కొంచెం నీరు తీసుకెళ్తున్నామని, అనుమతి లేకుండా జలనిధి దొంగిలించినందుకు రాజుగా క్షమాపణ కోరాడు. వెళ్ళేటప్పుడు ఒక సందేశం వదిలాడు: \"మీ జలాశయాలను శుభ్రంగా, సురక్షితంగా ఉంచుకోండి – మీరూ మాలాగా అంతరిక్ష జలచోరులు కావాల్సిన పరిస్థితి రాకూడదు. – మీ అంతరిక్ష జలచోర మిత్రుడు\".","pts":["లేఖకుడు: श्री प्रकाश – ప్రసిద్ధ హిందీ రచయిత; విచారోత్తేజక నిబంధాలు; పాఠం \"संचार माध्यमों के लिए विज्ञान\" పుస్తకం నుండి.","విధ: कहानी (విజ్ఞాన కల్పన కథ) – భవిష్యత్తులో జరగగల సంఘటనతో నీటి ప్రాముఖ్యత.","పాత్రలు: प्रो. दीपेश (భూవిజ్ఞాని), प्रो. विकास (ఇతర గ్రహాలపై జీవ పరిశోధకుడు), అంతరిక్ష యాత్రికుడు (ఆ గ్రహ రాజు).","సందేశం: జలాశయాలను శుభ్రంగా, సురక్షితంగా ఉంచాలి; నీటిని పొదుపుగా వాడాలి.","పఠన హేతు: \"क्या आपको पता है?\" (పీపీటీ నిబంధం – జెఫ్ బ్రెనమన్).","ఉపవాచకం: \"अनोखा उपाय\" (అనువాద కథ – డా. రావూరి భరద్వాజ)."],"w":[["सदी","శతాబ్దం"],["सर्वेक्षण","సర్వే"],["भूवैज्ञानिक","భూవిజ్ఞాన శాస్త్రవేత్త"],["यान","విమానం, వాహనం"],["अंतरिक्ष","అంతరిక్షం"],["मानवाकृति","మనిషి ఆకారం"],["प्रकाशवर्ष","కాంతి సంవత్సరం"],["मिशन","లక్ష్యం, పని"],["तबाही","వినాశనం"],["जलराशि","నీటి నిల్వ"],["विषाणु","వైరస్"],["महामारी","అంటువ్యాధి"],["जलनिधि","నీటి సంపద"],["टकटकी लगाना","కళ్ళార్పకుండా చూడటం"],["जलाशय","జలాశయం"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["\"जल\" से बने शब्द: जलचर, जलज, जलाशय, जलधि, जलप्रपात, जलवायु, जलपान.","विदेशज (आगत) शब्द: मिशन, लॉन, प्रोफ़ेसर, हैलो (अंग्रेज़ी); ख़बर, ज़िंदगी, ज़रूर, शाम (अरबी-फ़ारसी).","काल परिवर्तन: \"यह तो कोई यान है\" → \"यह तो कोई यान था\"; \"मर रहे थे\" → \"मर रहे हैं\".","अर्थ के आधार पर वाक्य: विस्मयादिबोधक (ओह!), प्रश्नवाचक, विधानवाचक, संदेहवाचक (होगा), संकेतवाचक (होता तो…न आते), इच्छावाचक (चाहिए), आज्ञावाचक/विनयसूचक (आइए), निषेधवाचक (मना है)."]},"qa":[["प्रो. दीपेश कौन थे?","भूवैज्ञानिक।"],["प्रो. विकास किस खोज में लगे थे?","ब्रह्मांड के अन्य ग्रहों पर जीवन की खोज में।"],["अंतरिक्षयात्री कहाँ से आये थे?","पृथ्वी से एक प्रकाशवर्ष दूर के ग्रह से।"],["वे पृथ्वी पर क्यों आये थे?","उनके ग्रह का जल विषाणुओं से ज़हरीला हो गया था, इसलिए पृथ्वी से जल ले जाने।"],["उनकी प्रार्थना (संदेश) क्या थी?","अपने जलाशयों को साफ़ और सुरक्षित रखें, ताकि आपको हमारी तरह जलचोर न बनना पड़े।"],["यान से उतरे व्यक्ति कौन थे?","उस ग्रह के राजा।"]],"act":"\"जल संरक्षण\" पर पी.पी.टी./पोस्टर बनाकर कक्षा में प्रस्तुत कीजिए; अपने गाँव में जल संरक्षण के उपायों की जानकारी दीजिए।","kn":"\"जल में अमृत है और जल में औषधियाँ हैं।\" – ऋग्वेद. \"हम जल की कीमत तब तक नहीं पहचानते, जब तक कुआँ सूख नहीं जाता।\"","qz":[["\"जल ही जीवन है\" के लेखक?","श्री प्रकाश","प्रेमचंद","काका कालेलकर","विष्णु प्रभाकर"],["यह पाठ किस विधा का है?","कहानी","एकांकी","पत्र","निबंध"],["कहानी किस समय की है?","इक्कीसवीं सदी का अंत","उन्नीसवीं सदी","अठारहवीं सदी","पंद्रहवीं सदी"],["प्रो. दीपेश क्या थे?","भूवैज्ञानिक","डॉक्टर","अध्यापक","राजा"],["अन्य ग्रहों पर जीवन की खोज कौन कर रहे थे?","प्रो. विकास","प्रो. दीपेश","राजा","पत्रकार"],["अंतरिक्षयात्री का ग्रह पृथ्वी से कितनी दूर?","एक प्रकाशवर्ष","दस किलोमीटर","सौ प्रकाशवर्ष","चाँद जितना"],["अंतरिक्षयात्री पृथ्वी को क्या कहते हैं?","नीला ग्रह","लाल ग्रह","हरा ग्रह","सुनहरा ग्रह"],["उनके ग्रह का जल किस कारण ज़हरीला हुआ?","विषाणुओं के कारण","धुएँ के कारण","प्लास्टिक के कारण","सूरज के कारण"],["वे पृथ्वी से क्या ले जा रहे थे?","जल","सोना","मिट्टी","पेड़"],["यान से उतरा व्यक्ति कौन था?","उस ग्रह का राजा","सैनिक","वैज्ञानिक","जासूस"],["पत्र में उसने अपने को क्या कहा?","अंतरिक्ष जलचोर मित्र","अंतरिक्ष राजा","दुश्मन","यात्री"],["\"विषाणु\" का अर्थ?","वायरस","विष","कीड़ा","दवा"],["\"यह यान कहाँ से आया?\" – वाक्य?","प्रश्नवाचक","विधानवाचक","निषेधवाचक","इच्छावाचक"],["\"नदी-नालों में कचरा बहाना मना है\" – वाक्य?","निषेधवाचक","प्रश्नवाचक","संदेहवाचक","विस्मयादिबोधक"]],"wb":{"mis":"\"होगा\" वाला वाक्य संदेहवाचक, \"होता तो… न आते\" संकेतवाचक, \"चाहिए\" इच्छावाचक। विदेशज शब्द अंग्रेज़ी/अरबी-फ़ारसी से आते हैं।","qz":[["\"ओह! यह तो कोई यान है।\" – वाक्य?","विस्मयादिबोधक","प्रश्नवाचक","आज्ञावाचक","संदेहवाचक"],["\"यहाँ का जल शुद्ध होगा।\" – वाक्य?","संदेहवाचक","निषेधवाचक","विधानवाचक","इच्छावाचक"],["\"हमारे यहाँ जल होता तो हम पृथ्वी पर न आते।\" – वाक्य?","संकेतवाचक","प्रश्नवाचक","आज्ञावाचक","विस्मयादिबोधक"],["\"यह तो कोई यान है\" – भूतकाल?","यह तो कोई यान था","यह तो कोई यान होगा","यह तो कोई यान हो","यह यान है"],["विदेशज शब्द?","मिशन","जल","पृथ्वी","आकाश"],["\"जल\" से बना शब्द – \"जल में रहने वाला\"?","जलचर","जलज","जलधि","जलवायु"]],"pg":"83–88","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":85,"lb":"పాఠ్యపుస్తకం","ws":["उन्मुखीकरण – विज्ञापन (प्रश्न) (పుట 83)","पाठ के पास के प्रश्न (పుట 86)","अर्थग्राह्यता-प्रतिक्रिया (పుట 87)","अभिव्यक्ति; भाषा की बात (పుట 88)"]},"tg":[["उन्मुखीकरण – विज्ञापन (प्रश्न) (పుట 83)",["1. जल (पानी) बचाने के बारे में। 2. (विज्ञापन में दिए समाचार-पत्र का नाम) 3. जल ही जीवन है – पानी की हर बूँद बचाओ, पानी बर्बाद मत करो।"]],["पाठ के पास के प्रश्न (పుట 86)",["4. पृथ्वी से एक प्रकाशवर्ष दूर के ग्रह से। 5. उनके ग्रह का जल विषाणुओं के कारण ज़हरीला हो गया था और महामारी फैल गई थी; जल शुद्ध होने तक पृथ्वी से कुछ जल ले जाने आए थे। 6. आप अपने जलाशयों को साफ़ और सुरक्षित रखें, ताकि आपको हमारी तरह अंतरिक्ष जलचोर न बनना पड़े; और हमें माफ़ कर दें।"]],["अर्थग्राह्यता-प्रतिक्रिया (పుట 87)",["अ) 1. जल के बिना जीवन संभव नहीं; पीने, खाना बनाने, नहाने, खेती, उद्योग, बिजली – सबके लिए जल चाहिए; पेड़-पौधे, पशु-पक्षी भी जल पर निर्भर हैं। 2. नल खुला न छोड़ूँगा, बाल्टी से नहाऊँगा, वर्षा जल संचय करूँगा, बचे पानी से पौधे सींचूँगा, टपकते नल ठीक कराऊँगा, जल स्रोतों को गंदा नहीं करूँगा।","आ) 1. पीने, खाना बनाने, नहाने, कपड़े-बर्तन धोने, सफ़ाई, बगीचे को सींचने के लिए। 2. सूखा, अकाल, फसलों का नाश, बीमारियाँ, पलायन, देशों-राज्यों में झगड़े, जीवों का विनाश। 3. वर्षा जल संचय, पेड़ लगाना, जल का सदुपयोग, जल स्रोतों की सफ़ाई, कारखानों का गंदा पानी नदियों में न छोड़ना, जन-जागरूकता।","इ) 1. प्रो. दीपेश ने आकाश में एक तारे जैसा यान पृथ्वी का चक्कर लगाते देखा और सोचा कि यह कोई जासूसी यान तो नहीं जो पृथ्वी पर हमला करना चाहता हो। 2. अंतरिक्षयात्री ने बताया कि वे पृथ्वी से जल ले जाने के विशेष उद्देश्य (मिशन) से आए हैं। 3. अंतरिक्ष जलचोर ने पत्र में संदेश दिया कि जलाशयों को साफ़-सुरक्षित रखें, वरना हमारी तरह जल के लिए दूसरे ग्रह पर चोरी करनी पड़ेगी।","ई) प्रश्न: 1. यह विज्ञापन किस मंत्रालय का है? 2. राष्ट्रीय किशोर स्वास्थ्य कार्यक्रम का उद्देश्य क्या है? 3. यह कार्यक्रम किन छह क्षेत्रों पर केंद्रित है? 4. इस कार्यक्रम से लगभग कितने किशोर लाभान्वित होंगे?"]],["अभिव्यक्ति; भाषा की बात (పుట 88)",["अ) 1. जल के बिना जीवन संभव नहीं – जल ही सब जीवों के जीवन का आधार है। 2. कुएँ, तालाब, नदियों की नियमित सफ़ाई; कचरा न डालना; चारों ओर पेड़ लगाना; वर्षा जल संचय; रिसाव रोकना। आ) हमारी ज़िम्मेदारी: जल बचाना, दूसरों को जागरूक करना, प्रदूषण रोकना, वर्षा जल संचय करना। इ) पोस्टर: \"जल है तो कल है – बूँद-बूँद बचाओ\"। ई) गाँव में चेक-डैम, इंकुडु गुंतलु (सोख गड्ढे), तालाबों की मरम्मत, ड्रिप सिंचाई द्वारा जल संरक्षण।","भाषा की बात 1. जलज, जलधि, जलाशय, जलप्रपात, जलवायु, जलपान 2. विदेशज शब्द: मिशन, लॉन, प्रोफ़ेसर, हैलो, ख़बर, ज़रूर, शाम","काल: 1. यह तो कोई यान था। 2. मेरे कई साथी इस संपूर्ण नीले ग्रह पर फैले हैं। 3. पानी के अभाव में हमारे लोग मर रहे हैं। 4. हम लोग अपना मिशन चुपचाप पूरा करना चाहते हैं।","प्रश्न वाक्य: पृथ्वी पर मानव ने क्या कर ली थी? / कहाँ मानव ने प्रगति कर ली थी?","अर्थ के आधार पर: 1. विस्मयादिबोधक 2. प्रश्नवाचक 3. विधानवाचक 4. संदेहवाचक 5. संकेतवाचक 6. इच्छावाचक 7. आज्ञावाचक (विनयसूचक) 8. निषेधवाचक","परियोजना: \"जल संरक्षण\" पर पी.पी.टी. – जल का महत्व, जल संकट, कारण, उपाय, नारे।"]]]},{"id":"hi12","no":12,"t":"धरती के सवाल अंतरिक्ष के जवाब","m":[11],"ty":"साक्षात्कार (ఇంటర్వ్యూ)","th":"आदर्श छात्र, विज्ञान, देशसेवा","by":"संकलित","sum":"ఈ పాఠంలో రెండు ఇంటర్వ్యూలు. (1) మాజీ రాష్ట్రపతి \"భారతరత్న\" ఏ.పీ.జే. అబ్దుల్ కలాం (రామేశ్వరం వీధుల్లో పత్రికలు అమ్మిన పేద బాలుడు) తో పిల్లలు: జనాభా సమస్యకు – మహిళా అక్షరాస్యత పెంచాలి, ప్రతి విద్యార్థి కనీసం ఐదుగురు నిరక్షర మహిళలకు చదువు నేర్పాలి; బాల కార్మిక వ్యవస్థ – చట్టప్రకారం నేరం; 2002 రాజ్యాంగ సవరణతో 6–14 ఏళ్ళ పిల్లలకు విద్య ప్రాథమిక హక్కు; పిల్లల ఆసక్తి, తల్లిదండ్రుల విద్య, యజమానుల ఆత్మనియంత్రణ ద్వారా నిర్మూలన; అవినీతి నిర్మూలన ఇంటి నుండి, బడి నుండి ప్రారంభం – తల్లి, తండ్రి, ప్రాథమిక ఉపాధ్యాయుడు నిజాయితీ నేర్పాలి; విద్యార్థికి ముఖ్యమైనవి – తన మీద నమ్మకం, ఇతరుల పట్ల గౌరవం; అభివృద్ధి చెందిన భారత్ కల కోసం – ఉన్నత లక్ష్యం, కష్టపడటం, నైతిక విలువలు, సెలవుల్లో పేద పిల్లలకు పాఠాలు, మొక్కలు నాటడం. (2) \"మిసైల్ ఉమెన్\", \"అగ్ని-పుత్రి\" టెస్సీ థామస్‌తో హైదరాబాద్‌లో ఇంటర్వ్యూ: కేరళ అలప్పుఝలో చదువు; గణితం, విజ్ఞానంపై ఇష్టం; DRDO లో అగ్ని మిసైల్ కార్యక్రమం – అగ్ని-5 డైరెక్టర్, దేశంలో మిసైల్ ప్రాజెక్ట్‌కు నాయకత్వం వహించిన తొలి మహిళ; ఆమె ఆదర్శం అబ్దుల్ కలాం (ఆమె గురువు); పిల్లలకు సందేశం – లక్ష్యం చేరే వరకు ఆగకుండా కష్టపడండి, విజయం మీ పాదాలను ముద్దాడుతుంది.","pts":["విధ: साक्षात्कार – ప్రత్యక్ష ప్రశ్నోత్తరాల ద్వారా ఒక ప్రముఖుడి విచారాలు, అనుభవాలు తెలుసుకోవడం.","ఏ.పీ.జే. అబ్దుల్ కలాం (అవుల్ పకీర్ జైనులాబ్దీన్ అబ్దుల్ కలాం) – రామేశ్వరం (తమిళనాడు); \"మిసైల్ మ్యాన్\", మాజీ రాష్ట్రపతి, భారతరత్న; పుస్తకం: \"हम होंगे कामयाब\".","2002 రాజ్యాంగ సవరణ – 6 నుండి 14 ఏళ్ళ పిల్లలకు విద్య ప్రాథమిక హక్కు.","టెస్సీ థామస్ – కేరళ (అలప్పుఝ); \"మిసైల్ ఉమెన్\", \"అగ్ని-పుత్రి\"; DRDO అగ్ని-5 కార్యక్రమ డైరెక్టర్; కలాం ఆమె గురువు, ఆదర్శం.","కలాం దృష్టిలో విద్యార్థికి ముఖ్య గుణాలు: ఆత్మవిశ్వాసం, ఇతరుల పట్ల గౌరవం.","DRDO = రక్షణ పరిశోధన మరియు అభివృద్ధి సంస్థ (रक्षा अनुसंधान और विकास संगठन)."],"w":[["साक्षात्कार","ఇంటర్వ్యూ"],["अंतरिक्ष","అంతరిక్షం"],["निर्धन","పేదవాడు"],["प्रतिभा","ప్రతిభ"],["लगन","పట్టుదల"],["जागरूकता","చైతన్యం"],["साक्षरता","అక్షరాస్యత"],["बाल मज़दूरी","బాల కార్మిక వ్యవస్థ"],["मौलिक अधिकार","ప్రాథమిక హక్కు"],["भ्रष्टाचार","అవినీతి"],["उन्मूलन","నిర్మూలన"],["संकल्प","దృఢ నిశ్చయం"],["वंचित","లేమిలో ఉన్న"],["प्रशंसक","అభిమాని"],["बुलंदी","ఉన్నత శిఖరం"]],"gr":{"t":"भाषा की बात (వ్యాకరణం)","p":["संधि: निर्धन = निः + धन (विसर्ग संधि); संकल्प = सम् + कल्प (व्यंजन संधि).","समास: सुबह-शाम – सुबह और शाम (द्वंद्व); युवाशक्ति – युवाओं की शक्ति (तत्पुरुष).","विलोम: संभव × असंभव, ज्ञान × अज्ञान, बढ़िया × घटिया, साकार × निराकार.","वचन: छात्रा – छात्राएँ, छुट्टी – छुट्टियाँ, पौधा – पौधे, बात – बातें."]},"qa":[["कलाम का जन्म कहाँ हुआ?","तमिलनाडु के रामेश्वरम में।"],["कलाम के अनुसार छात्र को कितनी महिलाओं को शिक्षित करना चाहिए?","कम से कम पाँच निरक्षर महिलाओं को।"],["भ्रष्टाचार उन्मूलन में कौन तीन लोग सहायक हैं?","माता, पिता और प्राथमिक विद्यालय के शिक्षक।"],["छात्र के लिए सबसे महत्वपूर्ण गुण?","अपने प्रति विश्वास और दूसरों के प्रति आदर।"],["टेसी थॉमस को क्या कहा जाता है?","\"मिसाइल वुमन\" और \"अग्नि-पुत्री\"।"],["टेसी थॉमस का आदर्श कौन है?","ए.पी.जे. अब्दुल कलाम।"]],"act":"छठवीं से दसवीं कक्षा तक की हिंदी पाठ्यपुस्तकों के मुखपृष्ठ (कवर पेज) देखकर कौन-सा सबसे अच्छा लगा – कारण सहित सूची बनाइए; किसी प्रसिद्ध व्यक्ति (वैज्ञानिक, खिलाड़ी, शिक्षक) का साक्षात्कार लीजिए।","kn":"\"विज्ञान समाज की भलाई के लिए होना चाहिए।\" – ए.पी.जे. अब्दुल कलाम. \"विज्ञान वरदान भी है और अभिशाप भी।\" – दिनकर. उपवाचक: \"अनोखा उपाय\" (डॉ. रावूरि भरद्वाज).","qz":[["यह पाठ किस विधा में है?","साक्षात्कार","कहानी","निबंध","एकांकी"],["अब्दुल कलाम का जन्म कहाँ हुआ?","रामेश्वरम","मदुरै","चेन्नई","हैदराबाद"],["बचपन में कलाम क्या बेचते थे?","समाचार पत्र","फल","मिठाई","खिलौने"],["कलाम को कौन-सा सम्मान मिला?","भारत रत्न","ज्ञानपीठ","ऑस्कर","अर्जुन"],["कलाम के अनुसार हर छात्र कितनी निरक्षर महिलाओं को पढ़ाए?","पाँच","दस","दो","सौ"],["6–14 वर्ष के बच्चों की शिक्षा मौलिक अधिकार किस वर्ष बनी?","2002","1950","1990","2010"],["भ्रष्टाचार उन्मूलन आंदोलन कहाँ से आरंभ हो?","घर और विद्यालय से","संसद से","बाज़ार से","अदालत से"],["छात्र के लिए सबसे महत्वपूर्ण गुण?","आत्मविश्वास और दूसरों का आदर","धन","प्रसिद्धि","ताकत"],["टेसी थॉमस को क्या कहा जाता है?","अग्नि-पुत्री","भारत कोकिला","लौह महिला","स्वर कोकिला"],["टेसी थॉमस किस मिसाइल कार्यक्रम की निदेशक बनीं?","अग्नि-5","पृथ्वी","आकाश","नाग"],["टेसी थॉमस की शिक्षा कहाँ हुई?","केरल","तमिलनाडु","आंध्र प्रदेश","दिल्ली"],["टेसी थॉमस का आदर्श कौन?","अब्दुल कलाम","सी.वी. रामन","होमी भाभा","विक्रम साराभाई"],["\"निर्धन\" का संधि विच्छेद?","निः + धन","नि + धन","निर + धन","निर्ध + न"],["\"सुबह-शाम\" में समास?","द्वंद्व","तत्पुरुष","द्विगु","अव्ययीभाव"]],"wb":{"mis":"\"निर्धन\" विसर्ग संधि (निः + धन), \"संकल्प\" व्यंजन संधि (सम् + कल्प)। \"युवाशक्ति\" तत्पुरुष (युवाओं की शक्ति), \"सुबह-शाम\" द्वंद्व।","qz":[["\"संकल्प\" का संधि विच्छेद?","सम् + कल्प","सं + कल्प","संक + ल्प","सन + कल्प"],["\"युवाशक्ति\" में समास?","तत्पुरुष","द्वंद्व","द्विगु","बहुव्रीहि"],["\"संभव\" का विलोम?","असंभव","संभावना","सुलभ","सरल"],["\"बढ़िया\" का विलोम?","घटिया","अच्छा","सुंदर","बड़ा"],["\"छुट्टी\" का बहुवचन?","छुट्टियाँ","छुट्टियों","छुट्टीएँ","छुट्टे"],["\"परिश्रम\" का पर्याय?","मेहनत","आराम","आलस्य","खेल"]],"pg":"91–98","f":"books/10/Class10_Hindi_Textbook_Sem1.pdf","p":93,"lb":"పాఠ్యపుస్తకం","ws":["पूर्व पठन (प्रश्न) (పుట 91)","पाठ के पास के प्रश्न (పుట 94)","पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 96)","व्याख्या, गद्यांश; अभिव्यक्ति (పుట 97)","भाषा की बात; परियोजना (పుట 98)"]},"tg":[["पूर्व पठन (प्रश्न) (పుట 91)",["1. राइट बंधुओं (ऑरविल और विल्बर राइट) ने। 2. मुझे भी पक्षी की तरह आकाश में ऊँचा उड़ने, पायलट या वैज्ञानिक बनने का मन करता है। 3. पशु-पक्षियों में उड़ने, तैरने, सूँघने की विशेष शक्ति है; मानव में बुद्धि, सोचने-समझने, आविष्कार करने और भाषा की शक्ति है।"]],["पाठ के पास के प्रश्न (పుట 94)",["1. प्रौढ़ शिक्षा, साक्षर भारत मिशन, सर्व शिक्षा अभियान, मध्याह्न भोजन, शिक्षा का अधिकार (2002/2009) जैसे कार्यक्रम। 2. आत्मविश्वास, दूसरों का आदर, अनुशासन, ईमानदारी, कड़ी मेहनत, नैतिक मूल्य। 3. ऊँचा लक्ष्य बनाकर खूब परिश्रम करे, ज्ञान प्राप्त करे, बाधाओं पर विजय पाए, नैतिक मूल्य अपनाए, छुट्टियों में वंचित बच्चों को पढ़ाए, पेड़ लगाए। 4. स्वयं ईमानदार रहकर, भ्रष्टाचारमुक्त जीवन का संकल्प लेकर, दूसरों के लिए उदाहरण बनकर, घर और विद्यालय से आंदोलन शुरू करके।"]],["पाठ के प्रश्न; अर्थग्राह्यता-प्रतिक्रिया (పుట 96)",["5. जो भी पढ़ें मन लगाकर, कड़ी मेहनत करें, लक्ष्य प्राप्त होने तक रुकें नहीं, जी-जान लगा दें – सफलता अवश्य कदम चूमेगी। 6. वे अग्नि मिसाइल कार्यक्रम से जुड़ी रहीं और अग्नि-5 की निदेशक बनीं, इसलिए उन्हें \"अग्नि-पुत्री\" कहा जाता है।","अ) 1. सी.वी. रामन, होमी जहाँगीर भाभा, विक्रम साराभाई, सतीश धवन, स्वामी विवेकानंद, महात्मा गांधी। 2. अब्दुल कलाम – निर्धन परिवार से उठकर अपनी प्रतिभा, परिश्रम, सादगी से वैज्ञानिक और राष्ट्रपति बने; बच्चों से बहुत प्रेम करते थे; (टेसी थॉमस – महिला होकर मिसाइल क्षेत्र में शिखर तक पहुँचीं)।","आ) 1. कुछ बालकों (छात्रों) ने उनके राष्ट्रपति कार्यकाल के दौरान। 2. एक महिला पत्रकार (साक्षात्कारकर्ता) ने हैदराबाद में उनके घर जाकर। 3. बाल मज़दूरी कानूनन अपराध है; बच्चों की पढ़ाई में रुचि जगाकर, माता-पिता को शिक्षित करके और मालिकों में आत्म-नियंत्रण पैदा करके इसे समाप्त किया जा सकता है। 4. केरल (अलप्पुझा) में; गणित और विज्ञान विषयों में रुचि थी।"]],["व्याख्या, गद्यांश; अभिव्यक्ति (పుట 97)",["इ) 1. कलाम कहते हैं कि भ्रष्टाचार मिटाने के लिए एक आंदोलन चाहिए जो घर और विद्यालय से शुरू हो; माता, पिता और प्राथमिक शिक्षक बच्चों को ईमानदारी सिखाएँ। 2. टेसी थॉमस कहती हैं कि कलाम केवल भारत के नहीं, पूरी दुनिया के आदर्श हैं, क्योंकि उन्होंने अंतरिक्ष और मिसाइल विज्ञान में भारत को विश्व में स्थान दिलाया।","ई) 1. विज्ञान रोचक और हमारे चारों ओर फैला विषय है – किताबों में कम, समझ में ज़्यादा बसता है। 2. ऋतुओं का बदलना, बीज से पौधा निकलना, पानी पर कागज़ की नाव तैरना, पक्षियों का उड़ना, तितली का फूल का रस चूसना, गुब्बारे का हवा से फूलना। 3. जो जानने की इच्छा (जिज्ञासा) नहीं रखता, वह कुछ नहीं सीख सकता।","अभि. अ) 1. आत्मविश्वास, दूसरों का आदर, ऊँचा लक्ष्य, कड़ी मेहनत, ज्ञान की प्यास, नैतिकता, ईमानदारी, सेवा-भाव, पर्यावरण प्रेम। 2. लगन, मेहनत और दृढ़ निश्चय से कोई भी लक्ष्य पाया जा सकता है; लड़कियाँ भी हर क्षेत्र में शिखर तक पहुँच सकती हैं; अपने गुरु और आदर्श का सम्मान करना चाहिए।","आ) 1. अच्छे नागरिक के गुण: कानून का पालन, ईमानदारी, कर्तव्यनिष्ठा, दूसरों का आदर, देशप्रेम, स्वच्छता, पर्यावरण संरक्षण, मतदान, कर भरना, भ्रष्टाचार का विरोध, सेवा-भाव, शिक्षा का प्रसार। 2. टेसी थॉमस ने डी.आर.डी.ओ. में कलाम के साथ काम किया; कलाम ने उन्हें प्रेरणा दी, मार्गदर्शन किया; कलाम का नेतृत्व बेमिसाल था, वे सादगी, ज्ञान और देशभक्ति के प्रतीक थे – इसलिए वे उन्हें अपना गुरु और आदर्श मानती हैं।","इ) शीर्षक: \"मिसाइल मैन से बच्चों की बातचीत\" / \"अग्नि-पुत्री टेसी थॉमस\" – साक्षात्कार अपने शब्दों में। ई) मैं ईमानदार रहूँगा, खूब मेहनत करूँगा, निरक्षरों को पढ़ाऊँगा, पेड़ लगाऊँगा, सबका आदर करूँगा, बड़े सपने देखकर उन्हें पूरा करूँगा।"]],["भाषा की बात; परियोजना (పుట 98)",["(अ) 1. प्रतिभा = योग्यता – उसकी योग्यता अद्भुत है; परिश्रम = मेहनत – मेहनत से सफलता मिलती है; छात्र = विद्यार्थी – विद्यार्थी अनुशासित हों; शिक्षा = विद्या – विद्या सबसे बड़ा धन है। 2. संभव × असंभव – मेहनत से असंभव भी संभव है; ज्ञान × अज्ञान – अज्ञान अंधकार है; बढ़िया × घटिया – घटिया सामान मत खरीदो; साकार × निराकार – ईश्वर निराकार भी माना जाता है। 3. छात्रा – छात्राएँ (छात्राएँ खेल रही हैं); छुट्टी – छुट्टियाँ (गर्मी की छुट्टियाँ); पौधा – पौधे (हमने पौधे लगाए); बात – बातें (अच्छी बातें सीखो)।","(आ) 1. निर्धन = निः + धन; संकल्प = सम् + कल्प 2. सुबह-शाम – द्वंद्व; युवाशक्ति – तत्पुरुष","(ई) एक नागरिक होने के नाते आप जिस देश में भी रहते हों…; एक खिलाड़ी होने के नाते आप जिस खेल में भी हों…; एक कलाकार होने के नाते आप जिस कला में भी हों…; एक अध्यापक होने के नाते आप जिस विषय/विद्यालय में भी पढ़ाते हों, आगे बढ़ने के लिए खूब परिश्रम करें।","परियोजना: कक्षा 6–10 की हिंदी पुस्तकों के मुखपृष्ठों की तुलना कर पसंद का कारण सहित सूची।"]]]}];
